# GDA cards: ART IMPORT for the Godot rebuild (Blender art -> Godot, modern look). Planner: Sonnet 5.5.
# MODE godot: see tools/cards/newcard.py. Contracts: docs/GODOT.md and docs/GODOT_PLANNER_BRIEF.md.
MODE = "godot"

BL = "Blender 5.2 is at `/opt/homebrew/bin/blender` and runs on the Mac (headless, no window, it does not steal focus). Run scripts like `/opt/homebrew/bin/blender --background --python-exit-code 1 --python tools/art/<script>.py -- <args>` (everything after the lone `--` is for your script: `sys.argv[sys.argv.index('--')+1:]`). Blender's Python has bpy, bmesh, mathutils and numpy; no PIL. You cannot see images: check files with `file`, `ls -l` and numbers your own checks print."
ART = "The Blender art tools (tools/art/*.py, docs/cars/*.json, docs/cars/details/*.json, docs/characters/*.json, docs/CAR_DOSSIER_SPEC.md, docs/CAR_DETAILS_SPEC.md, docs/art/*.md) live on the `dev` branch (checkout: /Users/leelangley/wt/webbwheresmycar/_dev). Your working copy must contain them (the planner merges `dev` before the GDA art cards run). If `ls tools/art/carlib.py` fails, finish with `STATUS: BLOCKED` and say so."
TREE = "Test rule: tests never need a running SceneTree. Every scene script has a public, idempotent `build()` that `_ready()` calls; the test instantiates the scene, calls `build()` itself, checks node facts, and frees the node with `node.free()` at the end. Do not call `get_tree()` or `add_child` onto the test itself."
SHOT = "Screenshot step: run `sh tools/godot/gshot.sh <scene> /tmp/<name>.png 30`. The output must contain NO line with `ERROR` (shader compile errors appear there). Then open the PNG with the Read tool and DESCRIBE what you see in your final reply (what is drawn, the main colours, anything cut off, black or missing). If it looks wrong, fix it."
TV = "docs/GODOT.md (plan, Compatibility renderer, pixel look, card rules)"
CLASSES = "paint, paint2, chrome, glass, lamp, tail, trim, tyre, wall"
GLB = "Car model contract (GDA01/GDA02): `res://art/cars/<id>.glb` has one MeshInstance3D node per part named `<class>_<NN>` (class is one of " + CLASSES + "; NN two digits) and each mesh surface has a material whose `resource_name` is exactly the class. Axes in Godot: the car faces +X, up is +Y, the near (screen) side is +Z, the model is built 10.0 m long whatever the real car (1 car unit = 0.1 m); the real length is `len_mm` in `res://art/cars/manifest.json`, so the in-game scale of a car is `len_mm / 10000.0`."

CARDS = [

 dict(id="GDA01", title="Blender glTF export of one car (export_glb.py)", needs=[],
  files=["tools/art/export_glb.py", "tools/art/test_export_glb.sh", "godot/art/cars/t1_chimp.glb"],
  goal="`tools/art/export_glb.py` builds ONE car in Blender exactly like tools/art/blender_car2.py does (same dossier, same parts) and exports it as a binary glTF `godot/art/cars/<id>.glb`: only meshes, one node per part named by material class, one material per class with the class as its name. Godot colours and weathers the parts by class at run time, so the glb only needs the shapes and the class names.",
  read=[ART, BL, "tools/art/blender_car2.py and tools/art/carlib.py (how a car is built; main() builds the scene, then renders)", "tools/art/cbmat.py (`class_of(name)`, `MASK_CLASS`, `hex_lin`, `make_all` material names)", "docs/cars/t1_chimp.json (a dossier: keys id, game_name, dims_mm.length, wheels, typical_paint) and docs/cars/details/t1_chimp.json (optional: paint.colour2, paint.finish)", GLB],
  steps=[
   "Header comment with the usage line `blender --background --python-exit-code 1 --python tools/art/export_glb.py -- --id t1_chimp [--out PATH] [--color #rrggbb] [--dossier-dir docs/cars]` and `python3 tools/art/export_glb.py --list`. Do `import bpy` only inside the build function so `--list` runs under plain python3. `argv = sys.argv[sys.argv.index('--')+1:] if '--' in sys.argv else sys.argv[1:]`. Defaults: `--dossier-dir docs/cars`, `--out godot/art/cars/<id>.glb`, `--color` = `typical_paint[0]` of the dossier. Bad or missing arguments: print a clear message and `sys.exit(2)`. `sys.dont_write_bytecode = True`.",
   "`--list`: for every `<dossier-dir>/*.json` (not in subfolders) that parses and has the keys `id` and `side_profile`, print `<id>` TAB `<game_name>`, sorted by id, then exit 0.",
   "Build: `sys.path.insert(0, <tools/art dir>)`; `import carlib, cbmat`; set `carlib.render = lambda *a, **k: None` (no render). Read the text of tools/art/blender_car2.py; build `sys.argv = ['blender_car2.py', '--', '--dossier', <dossier path>, '--out', '/tmp/export_glb_unused.png', '--color', <color>, '--w', '16', '--h', '8']` and APPEND `--details auto` only if the text contains the string `'--details'`, `--body loft` only if it contains `'--body'`, `--samples 1` only if it contains `'--samples'` (flags that do not exist yet must not be passed). Then `runpy.run_path(<tools/art/blender_car2.py>, run_name='__main__')`. The scene is now built in this Blender session.",
   "Clean the scene: delete every object that is not a MESH, and every mesh named `shadow_catcher` or with `is_shadow_catcher` true. For every mesh with more than one material slot: make it the only selected and active object, `bpy.ops.object.mode_set(mode='EDIT')`, `bpy.ops.mesh.separate(type='MATERIAL')`, `bpy.ops.object.mode_set(mode='OBJECT')`.",
   "Classify: `CLASS_EXTRA = {'lens': 'lamp', 'plate': 'wall', 'fabric': 'trim'}`; `cls_of(material_name)` strips a `.NNN` suffix, returns `CLASS_EXTRA[name]` when present, else `cbmat.class_of(name)`. For each remaining mesh take the class of its FIRST material (no material: `trim`) and store it in a dict `{object: class}`. Then, in this order: `obj.data.materials.clear()` on every mesh; remove EVERY material from `bpy.data.materials` (otherwise the new names get a `.001` suffix); create one canonical material per class that is used with `carlib.make_mat(name, cbmat.hex_lin(hex), metallic=, roughness=, emission=, emission_strength=)` using this table: paint = the `--color` value, metallic 0, roughness 0.32; paint2 = '#c8c8c8' (or paint.colour2 from docs/cars/details/<id>.json when that file and key exist), metallic 0, roughness 0.32; chrome '#f2f2f4' metallic 1 roughness 0.05; glass '#1b2830' roughness 0.02; lamp '#fff1c0' roughness 0.1 emission '#ffe9a8' strength 2.0; tail '#c01818' roughness 0.2 emission '#ff2010' strength 1.0; trim '#0e0e10' roughness 0.55; tyre '#16161a' roughness 0.85; wall '#e8e2d0' roughness 0.7. Append the canonical material of its class to each mesh. Rename every mesh object AND its mesh data to `<class>_<NN>`, NN counting from 00 per class in order of the old object names (sorted), so the result is repeatable.",
   "Export: select all objects; `props = bpy.ops.export_scene.gltf.get_rna_type().properties.keys()`; call `bpy.ops.export_scene.gltf(filepath=<out>, **kw)` where `kw` is the dict `{export_format: 'GLB', use_selection: True, export_apply: True, export_yup: True, export_cameras: False, export_lights: False, export_extras: False}` filtered to the keys present in `props` (create the output folder first). Print `EXPORTED <id> <out path> bytes=<file size>`.",
   "Meta: compute the bounding box of all remaining meshes in Blender world space (`obj.matrix_world @ Vector(corner)` over `obj.bound_box`), then convert to GODOT axes (Blender x,y,z -> Godot x, z, -y): `bbox_min = [minx, minz, -maxy]`, `bbox_max = [maxx, maxz, -miny]`, each rounded to 4 decimals. Print ONE line `META ` followed by `json.dumps(obj, sort_keys=True)` of `{id, game_name, len_mm (dossier dims_mm.length), bbox_min, bbox_max, wheelbase_units (max wheel x minus min wheel x of the dossier wheels, rounded to 2), wheels (count), classes ({class: number of objects}), paints (dossier typical_paint), paint2 (details paint.colour2 or empty string), finish (details paint.finish or 'solid')}`.",
   "`tools/art/test_export_glb.sh` (sh; first line after the shebang `cd \"$(dirname \"$0\")/../..\"` so it runs from the repo root; `mkdir -p /tmp/gda01`): (a) `python3 tools/art/export_glb.py --list` output contains the line `t1_chimp` TAB `Hillbilly Chimp`; (b) run the Blender export for t1_chimp with `--out /tmp/gda01/t1_chimp.glb`, require exit 0, `EXPORTED t1_chimp` and a `META ` line; (c) a python3 block reads the glb (12 byte header, first chunk is JSON: bytes 12..20 are length and type, JSON from byte 20) and requires: file starts with `glTF`; every material name is one of the 9 classes and the set includes paint, tyre, glass and chrome; every node name matches `^(paint|paint2|chrome|glass|lamp|tail|trim|tyre|wall)_[0-9][0-9]$`; the JSON has no `cameras` key and no `KHR_lights_punctual`; from META: `bbox_max[0] - bbox_min[0]` is between 9.5 and 10.6, `bbox_max[1]` between 3.0 and 4.5, `bbox_min[1]` between -0.05 and 1.0, `wheels` is 2 or more; (d) `--id nope` exits non-zero. Print `EXPORT GLB OK`.",
   "Then really export the car into the repo: run the Blender command with `--id t1_chimp` and no `--out` (writes godot/art/cars/t1_chimp.glb, about 300 KB) and commit that file."],
  accept=["`sh tools/art/test_export_glb.sh` prints `EXPORT GLB OK`.", "`python3 tools/art/export_glb.py --list` prints 8 lines (one per dossier in docs/cars) and exits 0.", "`ls -l godot/art/cars/t1_chimp.glb` shows a file between 100000 and 2000000 bytes."],
  oos=["Do not edit blender_car2.py, carlib.py, cbmat.py or any other tools/art file.", "Do not render images. Do not export the other cars (card GDA02)."]),

 dict(id="GDA02", title="Export every car to glb plus manifest.json", needs=["GDA01"],
  files=["tools/art/export_all_glb.sh", "tools/art/glb_manifest.py", "tools/art/test_export_all_glb.sh", "godot/art/cars/manifest.json",
         "godot/art/cars/t1_allergy.glb", "godot/art/cars/t1_alpaca.glb", "godot/art/cars/t1_chimp.glb", "godot/art/cars/t1_cooker.glb", "godot/art/cars/t1_maurice.glb", "godot/art/cars/t1_robbin.glb", "godot/art/cars/t1_trumpet.glb", "godot/art/cars/t1_volksbeagle.glb"],
  goal="One command exports every car with a dossier in docs/cars/ to `godot/art/cars/<id>.glb` and writes `godot/art/cars/manifest.json`, which Godot reads to know what cars exist, their game names, real lengths, boxes, wheelbase and paint colours.",
  read=[ART, BL, "tools/art/export_glb.py (GDA01: `--list` prints `<id>` TAB `<game_name>`; a Blender run prints `EXPORTED ...` and one `META {json}` line)", "tools/art/test_export_glb.sh (style of the shell tests)", GLB],
  steps=[
   "`tools/art/export_all_glb.sh [id]` (sh, `cd` to the repo root first). Ids: the one argument, or every first column of `python3 tools/art/export_glb.py --list`. For each id: `mkdir -p build/glb`; run `/opt/homebrew/bin/blender --background --python-exit-code 1 --python tools/art/export_glb.py -- --id $id > build/glb/$id.log 2>&1`; on exit 0 take the line of the log that starts with `META ` (text after the 5 character prefix) into `build/glb/$id.meta.json` and print `OK $id`; otherwise print `FAIL $id` and keep going. Afterwards run `python3 tools/art/glb_manifest.py build` and exit 1 if any car failed. Add nothing to .gitignore; `build/` is scratch.",
   "`tools/art/glb_manifest.py` (python3 standard library only). `build`: reads every `build/glb/*.meta.json` and writes `godot/art/cars/manifest.json` as `{\"version\": 1, \"cars\": {<id>: {\"file\": \"<id>.glb\", \"game_name\", \"len_mm\", \"bbox_min\", \"bbox_max\", \"wheelbase_units\", \"wheels\", \"classes\", \"paints\", \"paint2\", \"finish\"}}}` with `json.dump(..., sort_keys=True, indent=1)` and a trailing newline (byte-identical on a second run). Cars whose meta is missing are kept from the existing manifest if it exists. Prints `MANIFEST <n> cars`. `check`: for every car in the manifest requires the glb file to exist, to start with the 4 bytes `glTF`, `len_mm` > 2500, `wheels` >= 3 and `classes` to contain `paint` and `tyre`; prints `MANIFEST CHECK OK <n>` or the first problem and exit 1.",
   "`tools/art/test_export_all_glb.sh`: runs `sh tools/art/export_all_glb.sh` (all cars), requires `OK` lines for every id of `--list`, `MANIFEST 8 cars` (or the number of ids), runs `python3 tools/art/glb_manifest.py check`, runs `build` a second time and requires the manifest md5 (`md5 -q`) to be unchanged, requires `t1_chimp` game_name `Hillbilly Chimp` and `len_mm` 3556 in the manifest. Print `EXPORT ALL OK`.",
   "Run the full export once yourself and commit the 8 glbs and the manifest."],
  accept=["`sh tools/art/test_export_all_glb.sh` prints `EXPORT ALL OK`.", "`python3 tools/art/glb_manifest.py check` prints `MANIFEST CHECK OK 8`.", "`git status --short` lists only files from the list above."],
  oos=["Do not edit export_glb.py (a bug there: finish with STATUS: BLOCKED and the exact error).", "Cars without a dossier (only a details file) are skipped."]),

 dict(id="GDA05", title="Wear: numbers (wear.gd) and shader include", needs=["GDF01", "GDF02"],
  files=["godot/art/wear.gd", "godot/art/car_wear.gdshaderinc", "godot/tests/test_wear.gd"],
  goal="The weathering of a car as numbers (GDScript, testable) and as shader code (an include file the car shaders share). Port of the idea of src/art/sprite_wear.js: wear level 0 mint, 1 worn, 2 tatty, 3 wreck (a float 0..3 between the steps), layers dirt, rust, dents, pitting, glass crack, paint fade.",
  read=[TV, "src/art/sprite_wear.js and src/art/sprite_paint.js (read in the dev worktree /Users/leelangley/wt/webbwheresmycar/_dev: constants DIRT_AMOUNT, RUST_BLOBS, PIT_AMOUNT, FADE_LEVEL, FADE_TOWARD, wearState)", "godot/tests/harness.gd (GDF02: `ok`, `eq`, `near`)"],
  steps=[
   "`godot/art/wear.gd`: `class_name Wear`, `extends RefCounted`. Constants (PackedFloat32Array, index = wear state 0..3): `DIRT := [0.0, 0.1, 0.24, 0.4]`, `RUST := [0.0, 0.0, 0.10, 0.28]`, `PIT := [0.0, 0.0, 0.08, 0.18]`, `FADE := [0.0, 0.12, 0.30, 0.50]`, `DENT := [0.0, 0.0, 0.0, 1.0]`, `CRACK := [0.0, 0.0, 0.0, 1.0]`; `FADE_TOWARD := Color(\"b8aa96\")`.",
   "Static funcs: `clamp_level(w: float) -> float` (clamp to 0.0..3.0; NaN gives 0.0); `lerp_table(t: PackedFloat32Array, level: float) -> float` (linear between the two neighbouring entries of the clamped level; level 3.0 gives t[3]); `at(level: float) -> Dictionary` with float keys `dirt`, `rust`, `pit`, `fade`, `dent`, `crack` from the tables; `faded(c: Color, level: float) -> Color` = `c.lerp(FADE_TOWARD, lerp_table(FADE, level))`; `state_from_condition(cond: float) -> int` (port of wearState: NaN -> 0, cond >= 8 -> 0, >= 5 -> 1, >= 2.5 -> 2, else 3).",
   "`godot/art/car_wear.gdshaderinc` (plain shader code, no `shader_type` line; an include file for `#include \"res://art/car_wear.gdshaderinc\"`). Contents in this order: `const vec4 WR_DIRT = vec4(0.0, 0.1, 0.24, 0.4);` and the same for `WR_RUST` (0.0, 0.0, 0.10, 0.28), `WR_PIT` (0.0, 0.0, 0.08, 0.18), `WR_FADE` (0.0, 0.12, 0.30, 0.50); linear colour constants `const vec3 WR_FADE_TO = vec3(0.4793, 0.4020, 0.3050);` `WR_DIRT_A = vec3(0.1046, 0.0612, 0.0319)`, `WR_DIRT_B = vec3(0.0497, 0.0296, 0.0160)`, `WR_RUST_A = vec3(0.1070, 0.0232, 0.0060)`, `WR_RUST_B = vec3(0.3231, 0.0685, 0.0130)`, `WR_RUST_C = vec3(0.5841, 0.1946, 0.0319)`, `WR_PIT_C = vec3(0.1470, 0.1022, 0.0648)`, `WR_CRACK_C = vec3(0.5210, 0.7454, 0.8550)`.",
   "Functions in the include file (all prefixed `wr_`): `float wr_tab(vec4 t, float w)` { w = clamp(w, 0.0, 3.0); int i = int(min(floor(w), 2.0)); return mix(t[i], t[i + 1], w - float(i)); }; `float wr_hash(vec3 p)` { return fract(sin(dot(p, vec3(127.1, 311.7, 74.7))) * 43758.5453); }; `float wr_noise(vec3 p)` = trilinear value noise: `vec3 i = floor(p); vec3 f = fract(p); f = f * f * (3.0 - 2.0 * f);` then mix of the 8 `wr_hash(i + corner)` corners; `float wr_pit(vec3 p, float wear)` { return step(wr_hash(floor(p * 40.0)), wr_tab(WR_PIT, wear)); } (1.0 where chrome is pitted).",
   "`void wr_apply_paint(inout vec3 albedo, inout float rough, vec3 p, float hf, float wear)`: `p` is the object-space position, `hf` the height fraction 0 (sill) .. 1 (roof). In this order: (1) fade: `albedo = mix(albedo, WR_FADE_TO, wr_tab(WR_FADE, wear));` (2) dirt: `float lim = wr_tab(WR_DIRT, wear); float dn = wr_noise(p * 6.0); float dirt = step(hf, lim + (dn - 0.5) * 0.1) * step(0.001, lim);` colour `mix(WR_DIRT_B, WR_DIRT_A, wr_noise(p * 11.0))`; `albedo = mix(albedo, dirtcol, dirt); rough = mix(rough, 0.95, dirt);` (3) rust on the lower body only: `float cover = wr_tab(WR_RUST, wear); float rn = wr_noise(p * 3.0 + 7.0); float rust = step(1.0 - cover, rn) * step(0.001, cover) * (1.0 - smoothstep(0.35, 0.55, hf));` colour `mix(mix(WR_RUST_A, WR_RUST_B, wr_noise(p * 9.0)), WR_RUST_C, step(0.8, wr_noise(p * 17.0)))`; mix into albedo by `rust`, rough to 0.9 by `rust`. (4) dents, only when `wear > 2.0` (strength `clamp(wear - 2.0, 0.0, 1.0)`): three centres in object space `vec3(1.0, 1.4, 1.6)`, `vec3(-2.2, 1.2, -1.7)`, `vec3(3.0, 1.5, 1.5)` (metres, car 10 m long); for each `float s = 1.0 - smoothstep(0.0, 0.4, distance(p, c));` and `albedo *= 1.0 + strength * s * clamp((p.y - c.y) / 0.4, -1.0, 1.0) * -0.35;` (top darker, bottom lighter).",
   "`void wr_apply_chrome(inout vec3 albedo, inout vec3 emit, vec3 p, float wear)`: `float pit = wr_pit(p, wear); albedo = mix(albedo, WR_PIT_C, pit); emit *= 1.0 - pit;`. `void wr_apply_glass(inout vec3 albedo, vec3 p, float wear)`: only when `wear > 2.5`: a crack line `float d = abs(p.y - 2.6 - 0.5 * (p.x - 0.5)); float line = (1.0 - smoothstep(0.012, 0.03, d)) * step(abs(p.x - 0.5), 0.7) * clamp((wear - 2.5) * 2.0, 0.0, 1.0);` and `albedo = mix(albedo, WR_CRACK_C, line)`.",
   "`godot/tests/test_wear.gd` (`extends \"res://tests/harness.gd\"`): `at(0.0)` has the six keys `dirt`, `rust`, `pit`, `fade`, `dent`, `crack` and all are 0.0; `at(3.0).dirt` is 0.4, `.rust` 0.28, `.pit` 0.18, `.fade` 0.5, `.dent` 1.0, `.crack` 1.0; `at(1.5).dirt` near 0.17 (eps 1e-6); `at(2.0).rust` near 0.10; `at(9.0)` equals `at(3.0)` and `at(-1.0)` equals `at(0.0)`; `clamp_level(NAN)` is 0.0; `state_from_condition` of 8.0 -> 0, 7.9 -> 1, 5.0 -> 1, 4.99 -> 2, 2.5 -> 2, 2.49 -> 3, NAN -> 0; `faded(Color8(201, 111, 50), 3.0)` near `Color8(192, 140, 100)` per channel (eps 1.5/255); `faded(c, 0.0) == c`. Then read `res://art/car_wear.gdshaderinc` with `FileAccess.get_file_as_string` and `ok(txt.contains(...))` for each of: `float wr_tab(`, `float wr_noise(`, `float wr_pit(`, `void wr_apply_paint(`, `void wr_apply_chrome(`, `void wr_apply_glass(`, `vec4(0.0, 0.1, 0.24, 0.4)`, `vec4(0.0, 0.0, 0.10, 0.28)`, and `ok(not txt.contains(\"shader_type\"))`."],
  accept=["`sh tools/godot/gtest.sh test_wear` last line is `GDTEST OK`."],
  oos=["No scene, no material code (cards GDA04 and GDA18). The include is compiled and looked at in card GDA04; if GDA04 finds a compile error in it, GDA04 may fix the include."]),

 dict(id="GDA04", title="Car paint, chrome and glass shaders", needs=["GDA05"],
  files=["godot/art/car_paint.gdshader", "godot/art/chrome.gdshader", "godot/art/glass.gdshader", "godot/art/previews/mat_preview.gd", "godot/art/previews/mat_preview.tscn", "godot/tests/test_car_shaders.gd", "godot/art/car_wear.gdshaderinc"],
  goal="Three spatial shaders for the Compatibility renderer that make the car models look modern: a clear-coat style car paint (fresnel flop, bright highlight, colour parameter), a chrome with a fake environment reflection from a gradient ramp, and dark glass with a crack. All three use the wear include from GDA05 and a `wear` parameter 0..3.",
  read=[TV, "godot/art/car_wear.gdshaderinc and godot/art/wear.gd (GDA05: functions wr_apply_paint, wr_apply_chrome, wr_apply_glass)", "tools/art/cbmat.py (`make_paint`: facing colour flop; `make_chrome`; `make_glass`) and tools/art/cbrig.py (`_SKY_STOPS`: the studio sky ramp the chrome should mirror)", "Godot 4 spatial shader built-ins: NORMAL, VIEW, ALBEDO, ROUGHNESS, METALLIC, SPECULAR, EMISSION, INV_VIEW_MATRIX, and the `light()` function (SPECULAR_LIGHT, LIGHT, LIGHT_COLOR, ATTENUATION). The Compatibility renderer has NO clearcoat, so the coat is faked."],
  steps=[
   "`godot/art/car_paint.gdshader`: `shader_type spatial;` then `#include \"res://art/car_wear.gdshaderinc\"`. Uniforms (exact names): `uniform vec4 base_color : source_color = vec4(0.79, 0.44, 0.2, 1.0);` `uniform vec4 flop_color : source_color = vec4(0.88, 0.55, 0.3, 1.0);` `uniform float roughness_base : hint_range(0.0, 1.0) = 0.32;` `uniform float metallic_amount : hint_range(0.0, 1.0) = 0.0;` `uniform float coat : hint_range(0.0, 1.0) = 1.0;` `uniform float wear : hint_range(0.0, 3.0) = 0.0;` `uniform float ground_y = 0.0;` `uniform float body_height = 3.8;`. `varying vec3 v_obj;` set in `vertex()` to `VERTEX`. `fragment()`: `float ndv = clamp(dot(NORMAL, VIEW), 0.0, 1.0); float flop = pow(1.0 - ndv, 2.0); vec3 alb = mix(base_color.rgb, flop_color.rgb, flop); float r = roughness_base; float hf = clamp((v_obj.y - ground_y) / body_height, 0.0, 1.0); wr_apply_paint(alb, r, v_obj, hf, wear); ALBEDO = alb; ROUGHNESS = r; METALLIC = metallic_amount; SPECULAR = 0.6; float rim = pow(1.0 - ndv, 4.0); EMISSION = mix(base_color.rgb, vec3(1.0), 0.5) * rim * 0.25 * coat * (1.0 - clamp(wear / 3.0, 0.0, 1.0));` (the coat sheen fades as the car wears). `light()`: `vec3 h = normalize(VIEW + LIGHT); float s = pow(max(dot(NORMAL, h), 0.0), 96.0); float coat_k = coat * (1.0 - clamp(wear / 2.0, 0.0, 1.0)); SPECULAR_LIGHT += LIGHT_COLOR * ATTENUATION * s * 0.7 * coat_k;`.",
   "`godot/art/chrome.gdshader`: `shader_type spatial;` + the include. Uniforms: `uniform sampler2D env_ramp : source_color, repeat_disable, filter_linear;` `uniform float tint_strength = 1.0;` `uniform float wear : hint_range(0.0, 3.0) = 0.0;`. `varying vec3 v_obj;` from `VERTEX`. `fragment()`: `vec3 r = reflect(-VIEW, NORMAL); vec3 rw = normalize((INV_VIEW_MATRIX * vec4(r, 0.0)).xyz); float v = clamp(rw.y * 0.5 + 0.5, 0.0, 1.0); vec3 env = texture(env_ramp, vec2(v, 0.5)).rgb; float sun = smoothstep(0.92, 0.98, dot(rw, normalize(vec3(0.4, 0.7, 0.5)))); env += vec3(sun * 0.9); vec3 alb = vec3(0.05); vec3 emit = env * tint_strength; wr_apply_chrome(alb, emit, v_obj, wear); ALBEDO = alb; EMISSION = emit; METALLIC = 0.0; ROUGHNESS = 0.35; SPECULAR = 0.5;`.",
   "`godot/art/glass.gdshader`: `shader_type spatial;` + the include. Uniforms: `uniform vec4 glass_color : source_color = vec4(0.106, 0.157, 0.188, 1.0);` `uniform float wear : hint_range(0.0, 3.0) = 0.0;`. `varying vec3 v_obj;` `fragment()`: `vec3 alb = glass_color.rgb; wr_apply_glass(alb, v_obj, wear); ALBEDO = alb; ROUGHNESS = 0.05; METALLIC = 0.0; SPECULAR = 0.9; float ndv = clamp(dot(NORMAL, VIEW), 0.0, 1.0); EMISSION = vec3(0.35, 0.45, 0.55) * pow(1.0 - ndv, 3.0) * 0.4;` (opaque on purpose: the old sprite glass was opaque too).",
   "`godot/art/previews/mat_preview.gd` (`extends Node3D`; `build()` is idempotent and `_ready()` calls it) and `godot/art/previews/mat_preview.tscn` (root `Node3D` named `MatPreview` with that script). `build()` creates: a `WorldEnvironment` (Environment: `background_mode = Environment.BG_COLOR`, `background_color = Color(\"2b2550\")`, `ambient_light_source = Environment.AMBIENT_SOURCE_COLOR`, `ambient_light_color = Color(\"6e6a8c\")`, `ambient_light_energy = 0.9`); a `DirectionalLight3D` with `rotation_degrees = Vector3(-45, -35, 0)`; an orthographic `Camera3D` (`size = 8.0`, near 0.05, far 100, `transform = Transform3D(Basis(), Vector3(0, 2.4, 12)).looking_at(Vector3(0, 2.4, 0), Vector3.UP)`); and three rows of four spheres (`SphereMesh`, radius 0.8, height 1.6, one `MeshInstance3D` each) at x = -4.5, -1.5, 1.5, 4.5 and sphere-centre y = 0.8 (row 1), 2.4 (row 2), 4.0 (row 3), with `wear` = 0.0, 1.0, 2.0, 3.0 left to right. Row 1: ShaderMaterial of car_paint.gdshader with `base_color` `Color(\"c96f32\")`, `flop_color` `Color(\"e08c4c\")`, `body_height` 1.6 and `ground_y` -0.8 (a sphere mesh is centred on its own origin, so object-space y runs -0.8 to +0.8; with `body_height` 1.6 the height fraction runs 0 to 1 over the sphere; use the same two values for the paint spheres only). Row 2: ShaderMaterial of chrome.gdshader whose `env_ramp` is a `GradientTexture1D` (width 64) of a Gradient with exactly these 5 points (offset, colour): (0.0, 2a2432), (0.45, 2a2432), (0.5, e9dcc4), (0.6, b4c8e6), (1.0, 2b4a86). Row 3: ShaderMaterial of glass.gdshader. The `wear` parameter is set on all twelve.",
   "`godot/tests/test_car_shaders.gd`: for each of the three .gdshader files: `load()` returns a `Shader` that is not null; the file text (FileAccess) contains `shader_type spatial;`, `#include \"res://art/car_wear.gdshaderinc\"` and `uniform float wear`; car_paint also contains `uniform vec4 base_color : source_color`, `void light()` and `uniform float ground_y`; chrome contains `uniform sampler2D env_ramp`. A `ShaderMaterial` with car_paint: `set_shader_parameter(\"wear\", 2.0)` then `get_shader_parameter(\"wear\")` is 2.0. `MatPreview` smoke: instantiate `res://art/previews/mat_preview.tscn`, call `build()`, count MeshInstance3D children recursively: 12, and the `Camera3D` projection is `Camera3D.PROJECTION_ORTHOGONAL`; free it.",
   "Expected picture (3 rows x 4 spheres: orange paint with a bright highlight and a lighter edge, getting dirtier, rustier and duller left to right; chrome spheres reflecting a dark floor and a bright horizon and blue sky, pitted on the right; dark glass spheres, a pale crack line on the last one). " + SHOT.replace("<scene>", "art/previews/mat_preview.tscn").replace("<name>", "gda04") + " If a shader fails to compile fix it (you may edit the include `godot/art/car_wear.gdshaderinc` only to fix a compile error and must keep every name and constant that test_wear checks)."],
  accept=["`sh tools/godot/gtest.sh test_car_shaders` last line is `GDTEST OK`.", "`sh tools/godot/gtest.sh test_wear` still ends with `GDTEST OK`.", "`sh tools/godot/gshot.sh art/previews/mat_preview.tscn /tmp/gda04.png 30` prints `wrote /tmp/gda04.png` and no `ERROR` line; you viewed the PNG."],
  oos=["No CarView, no car models (GDA03). No material factory (GDA18)."]),

 dict(id="GDA18", title="CarMats: material per car part class", needs=["GDA04"],
  files=["godot/art/car_mats.gd", "godot/tests/test_car_mats.gd"],
  goal="`CarMats` makes the Godot material for each part class of a car model: the paint shader for paint and paint2, chrome and glass shaders, plain materials for lamp, tail, trim, tyre and wall. CarView (GDA03) uses it for every mesh surface.",
  read=[TV, GLB, "godot/art/car_paint.gdshader, chrome.gdshader, glass.gdshader (GDA04: exact uniform names)", "tools/art/cbmat.py (`make_lamp`, `make_tail`, `make_trim`, `make_tyre`, `make_whitewall` colours)"],
  steps=[
   "`godot/art/car_mats.gd`: `class_name CarMats`, `extends RefCounted`. `const CLASSES := PackedStringArray([\"paint\", \"paint2\", \"chrome\", \"glass\", \"lamp\", \"tail\", \"trim\", \"tyre\", \"wall\"])`. `static var _ramp: GradientTexture1D`.",
   "`static func env_ramp() -> GradientTexture1D`: builds once and caches: a `Gradient` with `offsets = PackedFloat32Array([0.0, 0.45, 0.5, 0.6, 1.0])` and `colors = PackedColorArray([Color(\"2a2432\"), Color(\"2a2432\"), Color(\"e9dcc4\"), Color(\"b4c8e6\"), Color(\"2b4a86\")])`, wrapped in a `GradientTexture1D` with `width = 64`.",
   "`static func make(cls: String, paint: Color, wear: float, ground_y: float = 0.0, body_h: float = 3.8) -> Material`. `wear` is clamped with `Wear.clamp_level`. Cases: `paint` and `paint2`: a `ShaderMaterial` of `res://art/car_paint.gdshader` with parameters `base_color` = paint, `flop_color` = `paint.lightened(0.1)`, `wear`, `ground_y`, `body_height` = body_h; `chrome`: ShaderMaterial of chrome.gdshader with `env_ramp` = `env_ramp()`, `wear`; `glass`: ShaderMaterial of glass.gdshader with `wear`; `lamp`: `StandardMaterial3D` albedo `fff1c0`, emission_enabled true, emission `ffe9a8`, emission_energy_multiplier 2.0, roughness 0.1; `tail`: albedo `c01818`, emission `ff2010`, energy 1.0, roughness 0.2; `trim`: albedo `0e0e10`, roughness 0.55; `tyre`: albedo `16161a`, roughness 0.85; `wall`: albedo `e8e2d0`, roughness 0.7. Any other `cls` returns the `trim` material. Every returned material gets `resource_name = cls`.",
   "`static func set_wear(m: Material, wear: float) -> void`: when `m` is a ShaderMaterial, `m.set_shader_parameter(\"wear\", Wear.clamp_level(wear))`; otherwise nothing.",
   "`godot/tests/test_car_mats.gd`: `make(\"paint\", Color.RED, 2.0)` is a ShaderMaterial whose `base_color` parameter equals `Color.RED` and `wear` is 2.0, `shader.resource_path` ends with `car_paint.gdshader`; `make(\"paint2\", ...)` same shader; `make(\"paint\", Color.RED, 9.0)` has wear 3.0; `make(\"chrome\", Color.WHITE, 0.0).get_shader_parameter(\"env_ramp\")` is the object returned by `env_ramp()` (same instance on a second call); `make(\"glass\", ...)` is a ShaderMaterial; each of lamp, tail, trim, tyre, wall is a `StandardMaterial3D` with `resource_name` equal to its class; lamp has `emission_enabled`; `make(\"zzz\", Color.WHITE, 0.0)` is a StandardMaterial3D whose `albedo_color` equals the albedo of `make(\"trim\", Color.WHITE, 0.0)`; for every name in `CLASSES` `make` returns non-null; `env_ramp().gradient.get_point_count()` is 5; `set_wear` on a paint material to 1.5 then `get_shader_parameter(\"wear\")` is 1.5, and on a StandardMaterial3D does not raise."],
  accept=["`sh tools/godot/gtest.sh test_car_mats` last line is `GDTEST OK`."],
  oos=["No scene nodes. No file under godot/art other than the two listed."]),

 dict(id="GDA03", title="CarView: 3D car in a pixel viewport", needs=["GDA02", "GDA18"],
  files=["godot/art/carview.gd", "godot/art/carview.tscn", "godot/art/previews/carview_demo.tscn", "godot/tests/test_carview.gd"],
  goal="`CarView` is the one node that shows a car: a SubViewport with an orthographic camera, a key light and a rim light, the car glb loaded by id, rendered at 1/3 size and scaled up with the nearest filter (the pixel look). Paint colour, wear 0..3 and view are set from code. This replaces the old car sprites everywhere (TV shop, garage, auction, diary, HUD portrait).",
  read=[TV, GLB, "godot/art/cars/manifest.json (GDA02: per car `file`, `game_name`, `len_mm`, `bbox_min`, `bbox_max`, `paint2`)", "godot/art/car_mats.gd and wear.gd (`CarMats.make(cls, paint, wear, ground_y, body_h)`, `Wear.clamp_level`)", "docs/art/CARS_ALIGN.md section on views (side view is THE default; front is the HUD face)", TREE],
  steps=[
   "`godot/art/carview.tscn`: exactly `[gd_scene load_steps=2 format=3]`, `[ext_resource type=\"Script\" path=\"res://art/carview.gd\" id=\"1\"]`, `[node name=\"CarView\" type=\"Control\"]` with properties `custom_minimum_size = Vector2(480, 240)`, `layout_mode = 3`, `anchors_preset = 0`, `script = ExtResource(\"1\")`. Nothing else: `build()` creates the children.",
   "`godot/art/carview.gd`: `class_name CarView`, `extends Control`. Consts: `CARS_DIR := \"res://art/cars/\"`, `TURN_SPEED := 0.6` (rad per second), `TARGET := Vector3(0.0, 0.75, 0.0)`, `DIST := 30.0`, `VIEWS := {\"side\": {\"yaw\": 0.0, \"pitch\": 3.0, \"size\": 3.2, \"shrink\": 3}, \"three_quarter\": {\"yaw\": 35.0, \"pitch\": 12.0, \"size\": 3.6, \"shrink\": 3}, \"front\": {\"yaw\": 90.0, \"pitch\": 4.0, \"size\": 2.4, \"shrink\": 3}, \"mini\": {\"yaw\": 0.0, \"pitch\": 3.0, \"size\": 3.6, \"shrink\": 2}}`. `@export var default_car := \"\"`. Vars: `car_id := \"\"`, `paint := Color(\"c96f32\")`, `wear := 0.0`, `view := \"side\"`. `static var _manifest: Dictionary`; `static func manifest() -> Dictionary` loads and caches `res://art/cars/manifest.json` with FileAccess and JSON (returns `{}` if missing).",
   "`build()` (idempotent: returns at once if node `Box` exists) creates this exact tree: `Box` (SubViewportContainer: `stretch = true`, `stretch_shrink = 3`, `texture_filter = CanvasItem.TEXTURE_FILTER_NEAREST`, `mouse_filter = Control.MOUSE_FILTER_IGNORE`, anchors full rect via `set_anchors_preset(Control.PRESET_FULL_RECT)`) > `VP` (SubViewport: `transparent_bg = true`, `own_world_3d = true`, `msaa_3d = Viewport.MSAA_DISABLED`, `render_target_update_mode = SubViewport.UPDATE_ALWAYS`) with children `Env` (WorldEnvironment with an Environment: `background_mode = Environment.BG_CLEAR_COLOR`, `ambient_light_source = Environment.AMBIENT_SOURCE_COLOR`, `ambient_light_color = Color(\"6e6a8c\")`, `ambient_light_energy = 0.9`), `Rig` (Node3D) with children `Cam` (Camera3D: `projection = Camera3D.PROJECTION_ORTHOGONAL`, `near = 0.05`, `far = 100.0`), `Key` (DirectionalLight3D: `rotation_degrees = Vector3(-45, -35, 0)`, `light_color = Color(\"fff2e0\")`, `light_energy = 1.2`, `shadow_enabled = true`) and `Rim` (DirectionalLight3D: `rotation_degrees = Vector3(-20, 150, 0)`, `light_color = Color(\"a8c4ff\")`, `light_energy = 0.7`); and `Pivot` (Node3D) with child `Blob` (MeshInstance3D: a `PlaneMesh` of size (1.0, 1.0) at y 0.01 with a `StandardMaterial3D`: `shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED`, `transparency = BaseMaterial3D.TRANSPARENCY_ALPHA`, `albedo_texture` = a `GradientTexture2D` (fill `Fill.FILL_RADIAL`, fill_from (0.5, 0.5), fill_to (1.0, 0.5), width 64, height 64, gradient from `Color(0,0,0,0.55)` at 0.0 to `Color(0,0,0,0)` at 1.0), `cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF`). At the end `set_view(\"side\")`. `_ready()` calls `build()` and, when `default_car != \"\"`, `set_car(default_car)`.",
   "`set_view(v: String) -> bool`: false (nothing changes) for an unknown name. Otherwise store `view`, set `Rig.rotation_degrees.y = yaw`, `Cam.size = size`, `Box.stretch_shrink = shrink`, and `Cam.transform = Transform3D(Basis(), TARGET + DIST * Vector3(0.0, sin(pitch_rad), cos(pitch_rad))).looking_at(TARGET, Vector3.UP)` (Rig-local space). Return true.",
   "`set_car(id: String) -> bool`: `m = manifest().get(\"cars\", {})`; unknown id or glb that fails to load as PackedScene: return false and change nothing. Otherwise free the old node `Car` (if any, `free()` immediately), `inst = scene.instantiate()`, `inst.name = \"Car\"`, `Pivot.add_child(inst)`; `s := float(len_mm) / 10000.0`; `inst.scale = Vector3(s, s, s)`; `bmin`/`bmax` from the manifest as Vector3; `inst.position = Vector3(-(bmin.x + bmax.x) * 0.5 * s, -bmin.y * s, -(bmin.z + bmax.z) * 0.5 * s)` (ground at y 0, centred, so the turntable spins round the middle). Scan all MeshInstance3D below `inst` and store a list of {mesh_instance, surface_index, cls} with `cls` = `mesh.surface_get_material(i).resource_name` when it is one of `CarMats.CLASSES`, else the node name before the first underscore if that is a class, else `trim`. Store `_ground := bmin.y`, `_body_h := bmax.y - bmin.y`. Resize `Blob`: `(bmax.x - bmin.x) * s * 1.15` by `(bmax.z - bmin.z) * s * 1.5` (PlaneMesh.size = Vector2(x_size, z_size)). Set `car_id = id`, call `_apply()`, return true.",
   "`_apply()`: for every stored surface call `mi.set_surface_override_material(i, CarMats.make(cls, col, wear, _ground, _body_h))` where `col` = `paint` for class paint, the manifest `paint2` colour (`Color(hex)`, or `paint` when the manifest string is empty) for class paint2, and `paint` (unused) for the others. `set_paint(c: Color)` stores and calls `_apply()`. `set_wear(w: float)` stores `Wear.clamp_level(w)` and calls `_apply()`. Both do nothing harmful when no car is set.",
   "`turntable(on: bool)`: `set_process(on)`. `_process(delta)`: `Pivot.rotation.y += TURN_SPEED * delta`. Also in `build()` call `set_process(false)`. Helpers for tests and other cards: `get_texture() -> Texture2D` (returns `VP.get_texture()`), `car_node() -> Node3D` (the `Car` node or null), `surface_classes() -> Dictionary` ({class: surface count}), `paint_materials() -> Array` (the materials currently set on paint and paint2 surfaces), `ground_y_px() -> float` = `size.y * 0.5 + 0.75 * cos(deg_to_rad(pitch)) * size.y / Cam.size` (the screen row of the ground under the car centre, from the current view's pitch).",
   "`godot/art/previews/carview_demo.tscn`: a hand-written scene: root `Control` named `Demo` (full rect, 1280x720), a `ColorRect` `Back` full rect colour `2b2550`, and an instance of `res://art/carview.tscn` named `CarView` with `layout_mode = 0`, `offset_left = 160.0`, `offset_top = 100.0`, `offset_right = 1120.0`, `offset_bottom = 580.0` and `default_car = \"t1_chimp\"` set on the instance (an `[ext_resource type=\"PackedScene\" ...]` plus `[node name=\"CarView\" parent=\".\" instance=ExtResource(\"2\")]`).",
   "`godot/tests/test_carview.gd`: (1) `cv = load(\"res://art/carview.tscn\").instantiate()`, `cv.build()`; node `Box/VP/Rig/Cam` exists and is orthogonal, `Box.stretch_shrink` 3, `Box.texture_filter` is NEAREST; `Box/VP/Pivot/Blob` exists. (2) `cv.set_car(\"nope\")` is false and `car_id` stays empty; `cv.set_car(\"t1_chimp\")` is true, `car_id` is `t1_chimp`, `car_node().scale.x` near 0.3556 (eps 1e-4); `surface_classes()` has `paint` >= 1, `tyre` >= 4, `glass` >= 1; the `Car` node's `position.y` is near `-bmin.y * 0.3556` using the manifest. (3) `set_paint(Color(1, 0, 0))`: every material of `paint_materials()` is a ShaderMaterial whose `base_color` equals red; `set_wear(5.0)` gives `wear` 3.0 and the paint materials' `wear` parameter 3.0; `set_wear(-2.0)` gives 0.0. (4) `set_view(\"front\")` is true, `Rig.rotation_degrees.y` near 90.0, `Cam.size` near 2.4; `set_view(\"mini\")` gives `Box.stretch_shrink` 2; `set_view(\"zzz\")` is false and the view is still `mini`. (5) `turntable(true)`: `is_processing()` true; `Pivot.rotation.y` 0 before, then `cv._process(1.0)` makes it near 0.6; `turntable(false)`: `is_processing()` false. (6) `get_texture()` is not null; with `cv.size = Vector2(480, 240)` and view `side`, `ground_y_px()` is near 176.2 (eps 0.5). Free `cv` at the end.",
   SHOT.replace("<scene>", "art/previews/carview_demo.tscn").replace("<name>", "gda03") + " Expected: a small orange rounded two-door car seen from the side, blocky pixels (about 3 screen pixels per art pixel), dark purple background, a soft dark shadow under the car, bright highlights on the roof and bonnet, shiny bumpers."],
  accept=["`sh tools/godot/gtest.sh test_carview` last line is `GDTEST OK`.", "`sh tools/godot/gshot.sh art/previews/carview_demo.tscn /tmp/gda03.png 30` prints `wrote /tmp/gda03.png` with no `ERROR` line; you viewed the PNG and described it."],
  oos=["No wear shader code, no showroom stage, no portrait. Do not edit wear.gd, car_mats.gd or any shader."]),

 dict(id="GDA19", title="Test: every exported car loads with all part classes", needs=["GDA03"],
  files=["godot/tests/test_art_cars.gd"],
  goal="A guard test over the whole car manifest: every car in `res://art/cars/manifest.json` has a glb that loads, instantiates and has the part classes Godot needs, and shows in a CarView.",
  read=[TV, GLB, "godot/art/carview.gd (GDA03 API: set_car, surface_classes, car_node)", TREE],
  steps=[
   "`godot/tests/test_art_cars.gd` (`extends \"res://tests/harness.gd\"`) with one method `test_every_car()`: `cars = CarView.manifest().get(\"cars\", {})`; `ok(cars.size() >= 8, \"manifest has 8 cars\")`. One shared `CarView` (instantiated from `res://art/carview.tscn`, `build()` called, freed at the end). For each id (sorted): `ps = load(\"res://art/cars/%s.glb\" % id)` is a PackedScene; `cv.set_car(id)` is true; `classes = cv.surface_classes()`; `ok` that every key of `classes` is one of `CarMats.CLASSES`, `classes.get(\"paint\", 0) >= 1`, `classes.get(\"tyre\", 0) >= 3`; manifest facts: `len_mm` between 2500 and 7000, `bbox_max[0] - bbox_min[0]` between 9.5 and 10.6, `bbox_min[1]` between -0.05 and 1.0, `wheels >= 3`, `game_name` is a non-empty ASCII String (no character code above 126), `paints` has at least 1 entry and each starts with `#` and has 7 characters; after `cv.set_wear(3.0)` and `cv.set_paint(Color(\"3b4a2f\"))` the `paint_materials()` array is not empty. Failure messages include the car id.",
   "`test_names()`: the game names in the manifest are unique."],
  accept=["`sh tools/godot/gtest.sh test_art_cars` last line is `GDTEST OK`."],
  oos=["Test only. If a car fails because of its model, report the id and the failing check in your final reply and finish with `STATUS: BLOCKED`."]),

 dict(id="GDA06", title="CarPortrait: real implementation on CarView", needs=["GDA03", "GDU19"],
  files=["godot/ui/car_portrait.gd", "godot/tests/test_car_portrait_art.gd"],
  goal="Card GDU19 made a placeholder `CarPortrait` (HUD selected-car slot, diary thumbnails) with the API `set_car(id, paint, wear)`. Replace the placeholder's drawing with a real `CarView` showing the car's front (HUD face) or mini view, behind the SAME public API.",
  read=[TV, "Find the placeholder: `grep -rl \"class_name CarPortrait\" godot/` (expected `godot/ui/car_portrait.gd`; if it lives elsewhere edit that file and say so) and read it fully: keep every public func, signal and var it has", "godot/art/carview.gd (GDA03 API: set_car, set_paint, set_wear, set_view, get_texture)", "docs/art/CARS_ALIGN.md: front = HUD face, mini = diary thumbnail", TREE],
  steps=[
   "Keep the class (`class_name CarPortrait`, same base class). Add `var view_name := \"front\"`, `var _cv: CarView`. `func set_car(id: String, paint, wear: float = 0.0) -> bool`: `paint` may be a Color or a String like `#c96f32` (`var c: Color = paint if paint is Color else Color(String(paint))`). Lazily create the child on first use (`_ensure_view()`: `_cv = preload(\"res://art/carview.tscn\").instantiate() as CarView`, `_cv.name = \"View\"`, `add_child(_cv)`, `_cv.build()`, `_cv.set_view(view_name)`, anchors full rect, `mouse_filter = Control.MOUSE_FILTER_IGNORE`). Then `_cv.set_car(id)`, `_cv.set_paint(c)`, `_cv.set_wear(wear)`; return the result of `set_car`. When the id is unknown (false), hide `View` and fall back to what the placeholder drew for an empty slot.",
   "Add `func set_portrait_view(v: String) -> bool` (forwards to `_cv.set_view(v)` and stores `view_name`; use `\"mini\"` for diary thumbnails) and `func get_view() -> CarView` (the child or null). Remove the placeholder's car-drawing code but keep its frame/background drawing if it had any. If the placeholder only drew a car, nothing else remains.",
   "`godot/tests/test_car_portrait_art.gd`: `p = CarPortrait.new()` (or the placeholder's documented way to make one); `p.set_car(\"t1_chimp\", Color(\"c96f32\"), 2.0)` is true; `p.get_view()` is not null, its `car_id` is `t1_chimp`, `view` is `front`, `wear` is 2.0; passing the paint as the String `#3b4a2f` works (the paint materials' `base_color` equals `Color(\"3b4a2f\")`); `p.set_car(\"nope\", Color.WHITE, 0.0)` is false and `get_view().visible` is false; `p.set_portrait_view(\"mini\")` is true and the CarView `view` is `mini`; `p.set_portrait_view(\"zzz\")` is false. Free `p`. All GDU19 tests must still pass."],
  accept=["`sh tools/godot/gtest.sh test_car_portrait_art` last line is `GDTEST OK`.", "`sh tools/godot/gtest.sh` (everything) still ends with `GDTEST OK`."],
  oos=["Do not change the portrait's public names or signals. No HUD layout changes."]),

 dict(id="GDA07", title="Showroom turntable scene", needs=["GDA03"],
  files=["godot/art/showroom.gd", "godot/art/showroom.tscn", "godot/tests/test_showroom.gd"],
  goal="`showroom.tscn`: the stage the SHOP channel shows a car on: purple back wall, tiled floor, spotlight cone and light pool, the car on a slow turntable, and a faint mirrored reflection on the floor. Colours come from src/art/showroom.js (read it in the dev worktree).",
  read=[TV, "/Users/leelangley/wt/webbwheresmycar/_dev/src/art/showroom.js (drawShowroom: wall #3B3470, seams #2F2A5C, dado #6C5EB5, floor #4A4180, spotlight cone and pool) and src/art/carfx.js (drawReflection: 0.16 alpha, 40 percent of car height)", "godot/art/carview.gd (GDA03: set_car, set_paint, set_wear, turntable, get_texture, ground_y_px)", TREE],
  steps=[
   "`godot/art/showroom.tscn`: root `Control` named `Showroom` with `custom_minimum_size = Vector2(596, 420)`, `layout_mode = 3`, `anchors_preset = 0`, `script = ExtResource(\"1\")` (res://art/showroom.gd). `showroom.gd`: `class_name Showroom`, `extends Control`, consts `W := 596`, `H := 420`, `FLOOR_Y := 300`.",
   "`build()` (idempotent; `_ready()` calls it; sets `size = Vector2(W, H)`) creates children in this order (names exact): `Wall` ColorRect (0,0,W,FLOOR_Y, `3B3470`); `Seams` - one ColorRect (2 px wide, FLOOR_Y high, `2F2A5C`) for every x = 64, 128, ... < W, children of a Control named `Seams`; `Dado` ColorRect (0, FLOOR_Y - 28, W, 4, `6C5EB5`); `Floor` ColorRect (0, FLOOR_Y, W, H - FLOOR_Y, `4A4180`); `Cone` Polygon2D (polygon (298, 0), (298 + 178, FLOOR_Y + 30), (298 - 178, FLOOR_Y + 30); color `Color(1.0, 0.9, 0.6, 0.10)`; material `CanvasItemMaterial` with `blend_mode = CanvasItemMaterial.BLEND_MODE_ADD`); `Pool` Polygon2D (a 32 point ellipse centre (298, FLOOR_Y + 60) radii (170, 18), `Color(1.0, 0.9, 0.6, 0.18)`, ADD material); `ReflectClip` Control (`clip_contents = true`) containing `Reflect` TextureRect (`texture = View.get_texture()`, `flip_v = true`, `modulate = Color(1, 1, 1, 0.16)`, `stretch_mode = TextureRect.STRETCH_SCALE`, `mouse_filter` ignore, `texture_filter` NEAREST); then `View` (instance of res://art/carview.tscn, so create it BEFORE ReflectClip in code but `move_child` it above `Pool`: final child order is Wall, Seams, Dado, Floor, Cone, Pool, View, ReflectClip). `View`: position (0, 40), size (W, 300), `set_view(\"three_quarter\")`, `turntable(true)`, `mouse_filter` ignore. Call `_place_reflection()` at the end.",
   "`_place_reflection()`: `g := View.position.y + View.ground_y_px()` (ground row in Showroom coordinates); `Reflect.size = View.size`; mirroring about the row g: `Reflect.position.y = (2.0 * g - (View.position.y + View.size.y)) - ReflectClip.position.y` with `ReflectClip.position = Vector2(0, g)`, `ReflectClip.size = Vector2(W, 60)` (so only the first 60 px under the ground line show; `Reflect.position.x = View.position.x`).",
   "Public API: `set_car(id: String) -> bool` (forwards to View, then `_place_reflection()`), `set_paint(c: Color)`, `set_wear(w: float)`, `spin(on: bool)` (`View.turntable(on)`), `spot_on(on: bool)` (`Cone.visible = on`, `Pool.visible = on`), `get_view() -> CarView`.",
   "`godot/tests/test_showroom.gd`: instantiate `res://art/showroom.tscn`, `build()`; child names in order are `Wall, Seams, Dado, Floor, Cone, Pool, View, ReflectClip`; `Seams` has 8 children (x = 64 .. 512 step 64); `Cone.material` is a CanvasItemMaterial with ADD blend; `set_car(\"t1_chimp\")` is true and `get_view().car_id` is `t1_chimp`; `spin(false)` makes `get_view().is_processing()` false and `spin(true)` true; `spot_on(false)` hides Cone and Pool, `spot_on(true)` shows them; `Reflect.flip_v` is true and its `texture` is the object `get_view().get_texture()`; `set_paint(Color(\"3b4a2f\"))` leaves the car set; `View.view` is `three_quarter`. Free the node.",
   SHOT.replace("<scene>", "art/showroom.tscn").replace("<name>", "gda07") + " Expected: purple wall with panel seams and a lighter rail, two-tone floor, a soft light cone from the top centre ending in a bright pool on the floor, the orange car at three-quarter view (the screenshot is 1280x720 so the 596x420 stage sits in the top-left corner), a faint upside-down copy of the car under it."],
  accept=["`sh tools/godot/gtest.sh test_showroom` last line is `GDTEST OK`.", "`sh tools/godot/gshot.sh art/showroom.tscn /tmp/gda07.png 30` prints `wrote /tmp/gda07.png` with no `ERROR` line; you viewed it and described it."],
  oos=["No channel code (the SHOP channel is a GDU card). No new shaders."]),

 dict(id="GDA08", title="Character frames export script (Mark, Dave)", needs=[],
  files=["tools/art/export_char_frames.py", "tools/art/test_export_char_frames.sh"],
  goal="Blender renders and pixelates the Mark and Dave sprites into `assets/art/characters/` with a `manifest.json` (card GC19, `sh tools/art/render_chars.sh all`). This script (plain python3, no Blender) copies exactly the PNGs the manifest lists into the Godot project and writes one JSON per character that Godot's `CharFrames` (GDA09) reads: clips with fps/loop/hold and neck positions, head faces by angle, busts.",
  read=[ART, "cards/GC19-*.md in the dev worktree (the manifest.json format: `characters.<name>.frame/head/clips/heads/head_back/bust/busts`, `scale.world`, `customers`)", "docs/characters/mark.json, docs/characters/poses_mark_front_a.json (clip fps, loop, hold, view)", "docs/GODOT.md"],
  steps=[
   "`tools/art/export_char_frames.py` (python3 standard library only). Usage: `python3 tools/art/export_char_frames.py [--src assets/art/characters] [--out godot/art/chars] [--char mark|dave|all] [--selftest]`. If `<src>/manifest.json` is missing: print `NO SOURCE: run sh tools/art/render_chars.sh all first` and exit 3.",
   "For each character name (`mark`, `dave`, or the one asked): read `manifest['characters'][name]`. Collect the ids to copy: every `clips.<clip>.frames[].id`, every id in `heads.<face>.<angle>`, `head_back`, every id in `busts`. Copy `<src>/<id>.png` to `<out>/<name>/<id>.png` (create folders) and DROP (and print `WARN missing <id>`) every id whose PNG does not exist: the dropped ids are removed from the clip frame lists (a clip left with no frames is removed), from heads and from busts. Write `<out>/<name>.json` with `json.dump(doc, indent=1, sort_keys=True)` plus a trailing newline: `{\"version\": 1, \"char\": name, \"scale\": manifest['scale']['world'], \"frame\": [w, h], \"head\": {\"size\": [w, h], \"pivot\": [x, y]}, \"bust\": [w, h], \"clips\": {clip: {\"view\", \"fps\", \"loop\", \"hold\", \"frames\": [{\"id\", \"neck\": [x, y], \"angle\"}]}}, \"heads\": {face: {angle: id}}, \"head_back\": id or \"\", \"busts\": {face: id}}`. Print `EXPORTED <name> clips=<n> frames=<n> heads=<n> busts=<n>` (heads = number of faces).",
   "Customers: when `manifest['customers']` is not empty write `<out>/customers.json` = `{job: {\"variants\": n, \"w\": w, \"h\": h, \"ids\": [...]}}` (only ids whose PNG exists) and copy those PNGs to `<out>/customers/`. Print `EXPORTED customers jobs=<n> files=<n>`.",
   "`--selftest`: in `tempfile.mkdtemp()` write a fake source (4x4 RGBA PNGs written with `zlib` and `struct`: signature, IHDR, IDAT, IEND with CRCs) and a manifest with mark: frame 144x144, head 80x80 pivot [40, 66], clips `idle` (view front, fps 3, loop true, hold 0, 2 frames, angle fwd, necks [72, 75] and [72, 76]) and `talk` (fps 6, loop true, hold 2, 3 frames), heads `neutral.fwd`, `talk_A.fwd`, `blink.fwd`, `head_back`, bust `neutral`; one frame id deliberately has NO png. Run the export into another temp folder and assert: the JSON parses, `clips.idle.frames` has 2 entries, `clips.talk.frames` has 2 (the missing one dropped), `frame` is [144, 144], `scale` 2, `head.pivot` is [40, 66], all copied PNG files exist, a second run gives a byte-identical JSON, no `customers.json` is written when the manifest has no customers. Print `CHAR EXPORT SELFTEST OK`.",
   "`tools/art/test_export_char_frames.sh`: runs `python3 tools/art/export_char_frames.py --selftest` and requires its last line; then, when `assets/art/characters/manifest.json` exists, runs the real export (`--char all`) and requires `EXPORTED mark` and `EXPORTED dave` and that `godot/art/chars/mark.json` parses; otherwise prints `SKIP real export (no assets/art/characters/manifest.json yet)`. Finally prints `EXPORT CHARS OK`. If the real export ran, commit `godot/art/chars/` (the planner will add it to the card list: say in your reply how many files and bytes)."],
  accept=["`python3 tools/art/export_char_frames.py --selftest` last line is `CHAR EXPORT SELFTEST OK`.", "`sh tools/art/test_export_char_frames.sh` last line is `EXPORT CHARS OK`.", "`python3 tools/art/export_char_frames.py --src /nonexistent` prints a line starting `NO SOURCE` and exits 3."],
  oos=["No Blender run. Do not render characters (card set GC owns that). Generated PNGs from a real run may be committed but are not required."]),

 dict(id="GDA09", title="CharFrames: SpriteFrames from the exported JSON", needs=["GDA08", "GDF02"],
  files=["godot/art/char_frames.gd", "godot/tests/test_char_frames.gd"],
  goal="`CharFrames` turns the JSON written by GDA08 (`res://art/chars/<char>.json`) into a `SpriteFrames` for an `AnimatedSprite2D`: one animation per clip with the right speed, loop flag and frame count, plus lookups for head faces and neck positions. Texture loading goes through a Callable so tests need no PNG files.",
  read=[TV, "tools/art/export_char_frames.py (GDA08: the JSON format: `frame`, `head`, `clips.<clip>.frames[].id/neck/angle`, `fps`, `loop`, `hold`, `view`, `heads.<face>.<angle>`, `head_back`, `busts`)", "godot/tests/harness.gd"],
  steps=[
   "`godot/art/char_frames.gd`: `class_name CharFrames`, `extends RefCounted`. `static func load_doc(char_id: String) -> Dictionary` (reads `res://art/chars/<char_id>.json`; `{}` when missing or invalid). `static func default_loader(char_id: String) -> Callable` returns `func(id: String) -> Texture2D: return load(\"res://art/chars/%s/%s.png\" % [char_id, id]) as Texture2D`.",
   "`static func build(doc: Dictionary, loader: Callable) -> SpriteFrames`: `var sf := SpriteFrames.new()`; remove the auto-created `default` animation (`sf.remove_animation(\"default\")`); for each clip name in sorted order: `sf.add_animation(name)`, `sf.set_animation_speed(name, float(fps))`, `sf.set_animation_loop(name, bool(loop))`, then for each frame `sf.add_frame(name, loader.call(id), 1.0)`; the `hold` value (extra frames to stay on the last picture) is added to the LAST frame's duration: its duration is `1.0 + float(hold)`. Frames whose loader returns null are skipped. Return `sf`.",
   "`static func build_char(char_id: String) -> SpriteFrames`: `build(load_doc(char_id), default_loader(char_id))`. `static func neck(doc: Dictionary, clip: String, frame: int) -> Vector2` (the `neck` of that frame; `Vector2.ZERO` when out of range). `static func clip_view(doc: Dictionary, clip: String) -> String` (`front` or `back`, default `front`). `static func head_id(doc: Dictionary, face: String, angle: String) -> String`: `doc.heads[face][angle]` when present, else `doc.heads[\"neutral\"][angle]`, else `doc.heads[\"neutral\"][\"fwd\"]`, else the empty string. `static func clip_names(doc: Dictionary) -> PackedStringArray` (sorted).",
   "`godot/tests/test_char_frames.gd`: a fake doc written in the test as a Dictionary: clips `idle` (view front, fps 3, loop true, hold 0, frames ids `m_idle_00`, `m_idle_01` with necks (72,75) and (72,76), angle fwd), `talk` (fps 6, loop true, hold 2, 3 frames `m_talk_00..02`), `back_idle` (view back, fps 2, loop false, 1 frame); heads `neutral: {fwd: \"m_head_fwd_neutral\", tilt_l: \"m_head_tilt_l_neutral\"}`, `talk_A: {fwd: \"m_head_fwd_talk_A\"}`; loader `func(id): var img := Image.create(4, 4, false, Image.FORMAT_RGBA8); return ImageTexture.create_from_image(img)`. Check: `clip_names` is `[\"back_idle\", \"idle\", \"talk\"]`; the SpriteFrames `get_animation_names()` has exactly those three (no `default`); `get_frame_count` is 2, 3, 1; `get_animation_speed` is 3.0, 6.0, 2.0; `get_animation_loop` is true, true, false; `get_frame_duration(\"talk\", 2)` is 3.0 and `get_frame_duration(\"talk\", 0)` is 1.0; `neck(doc, \"idle\", 1)` is `Vector2(72, 76)`; `neck(doc, \"idle\", 9)` is zero; `clip_view(doc, \"back_idle\")` is `back`; `head_id(doc, \"talk_A\", \"fwd\")` is `m_head_fwd_talk_A`; `head_id(doc, \"talk_A\", \"tilt_l\")` falls back to `m_head_tilt_l_neutral`; `head_id(doc, \"zzz\", \"up\")` falls back to `m_head_fwd_neutral`; `head_id({}, \"neutral\", \"fwd\")` is empty; a loader returning null for one id gives one frame fewer. `load_doc(\"nobody\")` is `{}`."],
  accept=["`sh tools/godot/gtest.sh test_char_frames` last line is `GDTEST OK`."],
  oos=["No Actor scene (GDA10). No real PNG needed by the tests."]),

 dict(id="GDA10", title="Actor scene: Mark and Dave with mouth flaps", needs=["GDA09"],
  files=["godot/art/actor.gd", "godot/art/actor.tscn", "godot/art/previews/actor_demo.gd", "godot/art/previews/actor_demo.tscn", "godot/tests/test_actor.gd"],
  goal="`Actor` is one character (Mark, Dave or a customer) on screen: a body `AnimatedSprite2D` playing a clip, with the head sprite placed on the neck position of the current frame and swapped between mouth shapes while `talk(text)` runs. Port of the idea of GC23 (animation clock, mouth shapes).",
  read=[TV, "godot/art/char_frames.gd (GDA09 API)", "/Users/leelangley/wt/webbwheresmycar/_dev/cards/GC23-*.md (blink and mouth shape idea) and docs/characters/expressions.json (face names such as talk_A talk_E talk_O talk_M neutral blink)", TREE],
  steps=[
   "`godot/art/actor.tscn`: root `Node2D` named `Actor`, `script = ExtResource(\"1\")` (res://art/actor.gd), `texture_filter = 1` (nearest). `actor.gd`: `class_name Actor`, `extends Node2D`, `signal clip_finished(clip: String)`, `const MOUTH_SEC := 0.09`, `const BLINK_EVERY := 3.2`, `const BLINK_SEC := 0.12`. `build()` (idempotent, `_ready()` calls it) creates `Body` (AnimatedSprite2D, `centered = false`) and `Head` (Sprite2D, `centered = false`), in that order, and connects `Body.frame_changed` to `_place_head` and `Body.animation_finished` to `_on_finished`.",
   "`setup(char_id: String) -> bool` loads the doc and `CharFrames.build_char(char_id)` and calls `setup_from(doc, loader)`; `setup_from(doc: Dictionary, loader: Callable) -> bool` (public, used by tests): false when the doc has no clips; otherwise stores `_doc`, `_loader`, sets `Body.sprite_frames = CharFrames.build(doc, loader)`, sets `scale = Vector2(float(doc.scale), float(doc.scale))`, and plays the clip `idle` (or the first clip) via `play`. Returns true.",
   "`play(clip: String) -> bool`: false if the SpriteFrames has no such animation; else `Body.play(clip)`, store `clip_name`, call `_place_head()`, true. `_place_head()`: `neck := CharFrames.neck(_doc, clip_name, Body.frame)`, `pivot := Vector2(_doc.head.pivot[0], _doc.head.pivot[1])`, `Head.position = neck - pivot`; texture: if `CharFrames.clip_view(_doc, clip_name) == \"back\"` the id `_doc.head_back`, otherwise `CharFrames.head_id(_doc, _face, angle_of_frame)` where `angle_of_frame` is the `angle` of the current frame entry (default `fwd`); `Head.texture = _loader.call(id)` (empty id: `Head.texture = null`). `_on_finished()` emits `clip_finished(clip_name)`.",
   "Mouth: `static func mouth_for(ch: String, prev: String) -> String`: lower-case letter a -> `talk_A`; e or i -> `talk_E`; o or u -> `talk_O`; m, b or p -> `talk_M`; space, comma, full stop, `!`, `?` -> `neutral`; any other letter or digit keeps `prev`. `static func mouth_schedule(text: String) -> PackedStringArray`: one entry per character, `prev` starts as `neutral` and is the previous entry. Example: `mouth_schedule(\"Oh no\")` is `[talk_O, talk_O, neutral, neutral, talk_O]`. `talk(text: String) -> float` stores the schedule, resets `_talk_t = 0.0`, returns `text.length() * MOUTH_SEC`; `stop_talk()` clears it and sets face `neutral`; `is_talking() -> bool`. `set_face(name: String)` sets `_face` and refreshes the head. `_process(delta)`: advance a blink timer (every `BLINK_EVERY` seconds the face is `blink` for `BLINK_SEC` unless talking); while talking `_talk_t += delta`, face = schedule[int(_talk_t / MOUTH_SEC)], and when `_talk_t >= text.length() * MOUTH_SEC` stop talking. Each change calls `_place_head()`.",
   "`godot/art/previews/actor_demo.gd` + `actor_demo.tscn` (root Node2D `ActorDemo`; `_ready()` adds a `ColorRect` 1280x720 colour `2b2550`, instantiates `res://art/actor.tscn` twice, `setup(\"mark\")` at position (300, 160) and `setup(\"dave\")` at (700, 160); if `setup` returns false for either, that actor is left out and a Label saying `no character art exported yet` is shown instead; calls `talk(\"Where is my car\")` on Mark).",
   "`godot/tests/test_actor.gd`: the fake doc of test_char_frames style (clips `idle` 2 frames, `talk` 3 frames, `back_idle` view back; heads neutral/talk_A/talk_E/talk_O/talk_M/blink at angle fwd; `head_back` id `m_head_back`; `head.pivot` [40, 66]; `scale` 2) and a loader returning a 4x4 `ImageTexture` per id, remembering the last id asked in a test-side Dictionary so the head texture can be compared by id. Check: `setup_from` true; `scale` is `Vector2(2, 2)`; `clip_name` is `idle`; `Head.position` equals neck minus pivot for frame 0; `play(\"talk\")` true, `play(\"zzz\")` false; `mouth_schedule(\"Oh no\")` equals the example above; `mouth_for(\"x\", \"talk_A\")` is `talk_A`; `talk(\"Mum\")` returns near 0.27 and `is_talking()`; the schedule for \"Mum\" is `[talk_M, talk_O, talk_M]`; after `_process(0.1)` (`_talk_t` 0.1, index 1) the face is `talk_O`; after a further `_process(0.3)` `is_talking()` is false and the face is `neutral`; `play(\"back_idle\")` makes the head texture the `m_head_back` one; `setup_from({}, loader)` is false. Free the node."],
  accept=["`sh tools/godot/gtest.sh test_actor` last line is `GDTEST OK`.", "If `godot/art/chars/mark.json` exists: `sh tools/godot/gshot.sh art/previews/actor_demo.tscn /tmp/gda10.png 30` prints `wrote /tmp/gda10.png` with no `ERROR` line and you describe the picture; otherwise say `no character art exported yet, screenshot skipped`."],
  oos=["No lip-sync from audio. No Game state access: callers decide what the actor says."]),

 dict(id="GDA11", title="Room plate export script (layers and lights JSON)", needs=[],
  files=["tools/art/export_room_layers.py", "tools/art/test_export_room_layers.sh"],
  goal="The Blender room pipeline (cards GE07-GE12, `sh tools/art/build_rooms.sh`) writes `assets/art/rooms/<room>.png` (+ `office_front.png`) and `assets/art/rooms/manifest.json`. This plain python3 script copies them to `godot/art/rooms/` as layer PNGs and writes `godot/art/rooms/<room>.json` with the layer list (parallax), the window sky rectangle and the light positions that `RoomPlate` (GDA12) turns into `PointLight2D` nodes.",
  read=[ART, "docs/art/GE.md (rooms, screen px, lamp / TV / window / strip / spot positions and colours; plates are 640x360 shown at x2 = 1280x720)", "cards/GE12-*.md (manifest format `{room: {file, w, h, scale, front?}}`) and cards/GE14-*.md (flicker: depth 0.12 lamp, 0.25 TV)", "docs/GODOT.md"],
  steps=[
   "`tools/art/export_room_layers.py` (python3 standard library only). Usage `python3 tools/art/export_room_layers.py [--src assets/art/rooms] [--out godot/art/rooms] [--room office|garage|auction|title|ledger|bookings|all] [--selftest]`. `<src>/manifest.json` missing: print `NO SOURCE: run sh tools/art/build_rooms.sh first` and exit 3.",
   "Module constant `LIGHTS` (stage pixels in the 1280x720 stage; `kind` is lamp, tv, window, strip, spot or sconce; `flicker` is the depth, 0 means steady; every entry also has `id`, `pos` [x, y], `color` hex, `energy`, `radius` in px, `seed`). office: `{id: lamp, kind: lamp, pos: [388, 328], color: #ffab55, energy: 0.45, radius: 170, flicker: 0.12, seed: 1.3}`, `{id: tv, kind: tv, pos: [625, 301], color: #78b4ff, energy: 0.30, radius: 230, flicker: 0.25, seed: 4.1}`, `{id: window, kind: window, pos: [110, 235], color: #b4c8e6, energy: 0.35, radius: 200, flicker: 0.0, seed: 0.0}`. garage: three strips `strip1..3` at pos [320, 130], [640, 130], [960, 130], color #dff1ff, energy 0.35, radius 240, flicker 0.30, seeds 2.0, 5.5, 8.1. auction: `{id: spot, kind: spot, pos: [640, 330], color: #ffe2a0, energy: 0.60, radius: 300, flicker: 0.0, seed: 0.0}`, sconces `sconce1` [120, 300] and `sconce2` [1160, 300], color #ffb070, energy 0.25, radius 120, flicker 0.15, seeds 3.3, 6.6. title: four lamps `lamp1..4` at [200, 330], [460, 330], [820, 330], [1080, 330], color #ffb15c, energy 0.40, radius 160, flicker 0.10, seeds 1.1, 2.2, 3.3, 4.4. ledger: `lamp` kind lamp at [260, 300], #ffab55, 0.40, 150, flicker 0.10, seed 1.3. bookings: `lamp` at [260, 300], #ffab55, 0.40, 150, flicker 0.10, seed 2.3. Constant `SKY` (the window / sky rectangle in stage px, or None): office `[30, 150, 160, 170]`; title `[0, 0, 1280, 720]`; all other rooms None. Constant `FRONT_PARALLAX = [6, 3]`.",
   "For each room in the manifest (or the chosen one): copy `<src>/<file>` to `<out>/<room>_mid.png` and, when the manifest entry has `front` and that PNG exists, `<src>/<front>` to `<out>/<room>_front.png` (print `WARN missing <file>` and skip the room if the plate itself is missing). Write `<out>/<room>.json` (`indent=1, sort_keys=True`, trailing newline): `{\"version\": 1, \"room\": room, \"scale\": entry.scale, \"size\": [entry.w, entry.h], \"sky\": {\"rect\": SKY[room]} or null, \"layers\": [{\"name\": \"mid\", \"file\": \"<room>_mid.png\", \"parallax\": [0, 0]}, (+ {\"name\": \"front\", \"file\": \"<room>_front.png\", \"parallax\": [6, 3]} when present)], \"lights\": LIGHTS.get(room, [])}`. Print `EXPORTED <room> layers=<n> lights=<n>`.",
   "`--selftest`: temp source folder with 4x4 PNGs (write them with `zlib` and `struct` like any PNG: signature, IHDR, IDAT, IEND, CRC) named `office.png`, `office_front.png`, `garage.png` and a manifest `{office: {file, w: 640, h: 360, scale: 2, front}, garage: {file, w: 640, h: 360, scale: 2}}`; export into another temp folder; assert: `office.json` has 2 layers (`mid`, `front`) with the front parallax [6, 3], `sky.rect` [30, 150, 160, 170], 3 lights of which the `lamp` has color `#ffab55` and `window` has `flicker` 0.0; `garage.json` has 1 layer, `sky` is None (null), 3 lights; `office_mid.png` and `office_front.png` exist; a second run is byte-identical; a manifest entry whose PNG is missing is skipped with a WARN. Print `ROOM EXPORT SELFTEST OK`.",
   "`tools/art/test_export_room_layers.sh`: runs the selftest and requires its last line; when `assets/art/rooms/manifest.json` exists runs the real export (`--room all`) and requires at least one `EXPORTED` line, otherwise prints `SKIP real export (no assets/art/rooms/manifest.json yet)`; then prints `EXPORT ROOMS OK`."],
  accept=["`python3 tools/art/export_room_layers.py --selftest` last line is `ROOM EXPORT SELFTEST OK`.", "`sh tools/art/test_export_room_layers.sh` last line is `EXPORT ROOMS OK`.", "`python3 tools/art/export_room_layers.py --src /nonexistent` prints a line starting `NO SOURCE` and exits 3."],
  oos=["No Blender run, no rendering of rooms (cards GE07-GE12). Light positions are first estimates from docs/art/GE.md; a later art QA pass tunes them."]),

 dict(id="GDA12", title="RoomPlate: layered room with lights and parallax", needs=["GDA11", "GDF02"],
  files=["godot/art/room_plate.gd", "godot/tests/test_room_plate.gd"],
  goal="`RoomPlate` (a Node2D) shows one room from the JSON of GDA11: an optional sky gradient behind the window, the room plate, the front layer that shifts a little against the pointer (parallax), and one `PointLight2D` per light with flicker; the window light is cold and the lamp light warm; `set_hour` changes the sky and the window light. Port of src/art/roomfx_light.js (`flicker`), roomfx_world.js (`skyColors`) and rooms.js (parallax).",
  read=[TV, "tools/art/export_room_layers.py (GDA11: the JSON format and the LIGHTS table)", "/Users/leelangley/wt/webbwheresmycar/_dev/src/art/roomfx_light.js (flicker formula) and src/art/roomfx_world.js (skyColors)", "godot/tests/harness.gd", TREE],
  steps=[
   "`godot/art/room_plate.gd`: `class_name RoomPlate`, `extends Node2D`. Static funcs: `flicker(t: float, seed: float, depth: float) -> float` = `1.0 - depth * (0.5 + 0.5 * (0.6 * sin(t * 7.3 + seed) + 0.4 * sin(t * 17.9 + seed * 2.1)))`; `sky_colors(hour: int) -> Dictionary` with Color values `top` and `bottom`: hours 6 to 8 `#3b4a8a` / `#f2a65a`; 9 to 16 `#6fb4ee` / `#d8efff`; 17 to 19 `#4a3a7a` / `#f08a5d`; otherwise `#0b0d24` / `#1d2450`; `radial_texture() -> GradientTexture2D` (cached in a `static var`; `fill = GradientTexture2D.FILL_RADIAL`, `fill_from = Vector2(0.5, 0.5)`, `fill_to = Vector2(1.0, 0.5)`, 128x128, gradient white alpha 1.0 at offset 0.0 to white alpha 0.0 at offset 1.0).",
   "`build_from(doc: Dictionary, loader: Callable) -> bool` (loader takes a file name String and returns a Texture2D): false when `doc` has no `layers`. Clears earlier children (free them) then creates in this order: if `doc.sky` is a Dictionary: `Sky` (Sprite2D, `centered = false`, `texture` = a `GradientTexture2D` 4x64 vertical gradient (fill linear, fill_from (0, 0), fill_to (0, 1)), `position` = rect x, y, `scale` = rect w / 4, rect h / 64; `light_mask = 2`); then one `Sprite2D` per layer named by `layer.name` (`centered = false`, `texture = loader.call(layer.file)`, `scale = Vector2(doc.scale, doc.scale)`, `texture_filter = CanvasItem.TEXTURE_FILTER_NEAREST`, `light_mask = 2`) and remembers its parallax; then one `PointLight2D` per light named by `light.id` (`texture = radial_texture()`, `texture_scale = 2.0 * radius / 128.0`, `color`, `energy`, `position = Vector2(pos)`, `range_item_cull_mask = 2`, `blend_mode = Light2D.BLEND_MODE_ADD`, `shadow_enabled = false`), remembering base energy, `flicker` depth and `seed`. Stores `room_id`. Calls `set_hour(12)` and `set_look(Vector2.ZERO)`. Returns true.",
   "`load_room(id: String) -> bool`: reads `res://art/rooms/<id>.json` (FileAccess + JSON; false when missing) and calls `build_from(doc, func(f): return load(\"res://art/rooms/\" + f) as Texture2D)`. `set_look(v: Vector2)`: clamp each component to -1..1; each layer sprite gets `position = Vector2(-v.x * px, -v.y * py).round()` where `[px, py]` is its parallax (the `mid` layer has [0, 0] so it never moves). `layer_node(name: String) -> Sprite2D`, `light_node(id: String) -> PointLight2D`, `sky_node() -> Sprite2D` (null if none).",
   "`set_hour(h: int)`: if a Sky exists set its gradient to `sky_colors(h)` (top, bottom). Window light (the light whose `kind` is `window`): day (9 to 16) colour `#b4c8e6`, energy = base; dusk (6 to 8 and 17 to 19) colour `#f2a65a`, energy = base * 0.8; night colour `#9db4ff`, energy = base * 0.35, where `base` is always the energy from the doc (never the previous hour's value; flicker multiplies the value set here). Lamp-kind lights (`lamp`, `sconce`, `spot`, `strip`) are never recoloured, so they stay warm (or strip white). `_process(delta)`: `_t += delta`; for each light with `flicker > 0` set `energy = base * flicker(_t, seed, depth)`.",
   "`godot/tests/test_room_plate.gd`: `flicker(0.0, 1.3, 0.12)` near 0.895710 (eps 1e-5); `flicker(1.0, 1.3, 0.12)` near 0.890087 (eps 1e-5); for t in 0..20 step 0.1 the value for depth 0.12 stays within [0.88, 1.0]; `sky_colors(12).top` is `Color(\"6fb4ee\")`, `sky_colors(7).bottom` is `Color(\"f2a65a\")`, `sky_colors(18).top` is `Color(\"4a3a7a\")`, `sky_colors(2).top` is `Color(\"0b0d24\")`. A fake doc (office-like: scale 2, size [640, 360], sky rect [30, 150, 160, 170], layers `mid` parallax [0, 0] and `front` parallax [6, 3], lights lamp (#ffab55, energy 0.45, radius 170, flicker 0.12, seed 1.3), window (#b4c8e6, energy 0.35, radius 200, flicker 0.0), tv (#78b4ff, 0.30, 230, 0.25, 4.1)) with a loader returning a 4x4 ImageTexture: `build_from` true; children names in order are `Sky, mid, front, lamp, window, tv`; `layer_node(\"mid\").scale` is (2, 2); `set_look(Vector2(1, -1))` puts `front` at `Vector2(-6, 3)` and `mid` at zero; `set_look(Vector2(9, 0))` clamps to -6 in x; `lamp.color.r > lamp.color.b` (warm) and (hour 12) `window.color.b > window.color.r` (cold); `set_hour(23)`: window energy near 0.35 * 0.35 and colour `#9db4ff`; `set_hour(7)`: window colour `#f2a65a`; `_process(0.5)` then the lamp energy equals `0.45 * flicker(0.5, 1.3, 0.12)` (eps 1e-6) while the window energy is unchanged; the Sky texture gradient's first colour for hour 12 is `Color(\"6fb4ee\")`; `build_from({}, loader)` is false. Free the node."],
  accept=["`sh tools/godot/gtest.sh test_room_plate` last line is `GDTEST OK`.", "No screenshot in this card (no preview scene yet; room scenes come with the GDR cards)."],
  oos=["No room scenes (office.tscn etc. belong to the GDR cards). No CanvasModulate or global lighting changes."]),

 dict(id="GDA13", title="Post-process screen shader (vignette, grain, glow)", needs=["GDF01", "GDF02"],
  files=["godot/art/post.gdshader", "godot/art/post.gd", "godot/art/post.tscn", "godot/tests/test_post.gd"],
  goal="A full-screen post-process layer: soft vignette, subtle film grain and a bloom-like glow on bright pixels, optional scanlines, as a `CanvasLayer` that can be switched on and off from the game settings (the `crt` setting of src/game.js DEFAULT_SETTINGS; Game keeps the settings Dictionary with keys `crt`, `sound`, `music`).",
  read=[TV, "/Users/leelangley/wt/webbwheresmycar/_dev/src/art/crt.js (scanline spacing 3 px, vignette corner 0.45) and roomfx_light.js (vignette, grain) for the look", "Godot 4 canvas_item shaders: `uniform sampler2D screen_tex : hint_screen_texture, filter_linear_mipmap;`, `textureLod`, `SCREEN_UV`"],
  steps=[
   "`godot/art/post.gdshader`: `shader_type canvas_item;` Uniforms: `uniform sampler2D screen_tex : hint_screen_texture, filter_linear_mipmap, repeat_disable;` `uniform float vignette : hint_range(0.0, 1.0) = 0.3;` `uniform float grain : hint_range(0.0, 0.2) = 0.04;` `uniform float glow : hint_range(0.0, 1.0) = 0.25;` `uniform float glow_threshold : hint_range(0.0, 0.95) = 0.7;` `uniform float scanlines : hint_range(0.0, 1.0) = 0.0;` `uniform float time_s = 0.0;`. `float hash21(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }`. `fragment()`: `vec3 c = texture(screen_tex, SCREEN_UV).rgb;` glow: `vec3 b = (textureLod(screen_tex, SCREEN_UV, 2.0).rgb + textureLod(screen_tex, SCREEN_UV, 3.0).rgb) * 0.5; b = max(b - vec3(glow_threshold), vec3(0.0)) / (1.0 - glow_threshold); c += b * glow;` vignette: `vec2 q = (SCREEN_UV - 0.5) * vec2(1.7778, 1.0); c *= 1.0 - vignette * smoothstep(0.45, 1.0, length(q));` grain: `float n = hash21(floor(SCREEN_UV * vec2(640.0, 360.0)) + floor(time_s * 12.0) * 17.0); c += (n - 0.5) * grain;` scanlines: `c *= 1.0 - scanlines * 0.5 * (0.5 + 0.5 * sin(SCREEN_UV.y * 720.0 * 3.14159));` then `COLOR = vec4(clamp(c, 0.0, 1.0), 1.0);`.",
   "`godot/art/post.tscn` exactly: `[gd_scene load_steps=4 format=3]`, `[ext_resource type=\"Script\" path=\"res://art/post.gd\" id=\"1\"]`, `[ext_resource type=\"Shader\" path=\"res://art/post.gdshader\" id=\"2\"]`, `[sub_resource type=\"ShaderMaterial\" id=\"ShaderMaterial_1\"]` with `shader = ExtResource(\"2\")`, `[node name=\"Post\" type=\"CanvasLayer\"]` with `layer = 100` and `script = ExtResource(\"1\")`, `[node name=\"Rect\" type=\"ColorRect\" parent=\".\"]` with `material = SubResource(\"ShaderMaterial_1\")`, `anchors_preset = 15`, `anchor_right = 1.0`, `anchor_bottom = 1.0`, `mouse_filter = 2`.",
   "`godot/art/post.gd`: `class_name PostFx`, `extends CanvasLayer`. `var _t := 0.0`. `set_enabled(on: bool)`: `visible = on` and `set_process(on)`; `is_enabled() -> bool` = `visible`. `set_param(name: String, v: float) -> bool`: only for `vignette`, `grain`, `glow`, `glow_threshold`, `scanlines` (returns false for any other name); calls `$Rect.material.set_shader_parameter(name, v)`; `get_param(name: String) -> float`. `apply_settings(s: Dictionary)`: `set_enabled(bool(s.get(\"crt\", false)))` and, when the key `scanlines` is a number, `set_param(\"scanlines\", ...)`. `_process(delta)`: `_t += delta; $Rect.material.set_shader_parameter(\"time_s\", _t)`. `_ready()`: `set_enabled(false)` (off until the settings say so).",
   "`godot/tests/test_post.gd`: the shader file text contains `shader_type canvas_item;`, `hint_screen_texture`, `uniform float vignette`, `uniform float grain`, `uniform float glow`, `textureLod(`; instantiate `res://art/post.tscn` (no build needed); `layer` is 100; `Rect` is a ColorRect with `mouse_filter` 2 and a ShaderMaterial whose shader is not null; `set_param(\"grain\", 0.1)` is true and `get_param(\"grain\")` is 0.1; `set_param(\"nope\", 1.0)` is false; `set_enabled(true)` makes `is_enabled()` true and `is_processing()` true; `apply_settings({\"crt\": false})` makes `is_enabled()` false; `apply_settings({\"crt\": true, \"scanlines\": 0.5})` makes it true and `get_param(\"scanlines\")` 0.5; `apply_settings({})` makes it false. Free the node.",
   "Screenshot check of the shader on a visible picture: `sh tools/godot/gshot.sh art/post.tscn /tmp/gda13.png 10` only shows an empty screen (the layer starts disabled), so just require that the command prints `wrote /tmp/gda13.png` and no `ERROR` line (that proves the shader compiles under real GL); view it and say it is a plain empty frame."],
  accept=["`sh tools/godot/gtest.sh test_post` last line is `GDTEST OK`.", "`sh tools/godot/gshot.sh art/post.tscn /tmp/gda13.png 10` prints `wrote /tmp/gda13.png` and no `ERROR` line."],
  oos=["Do not add the layer to the main scene (a GDR card does that). No CRT curvature (the TV screen has its own CRT shader in a GDU card)."]),

 dict(id="GDA14", title="Particle effect scenes: steam, dust, cash, confetti, smoke", needs=["GDF02"],
  files=["godot/art/fx/fx.gd", "godot/art/fx/steam.tscn", "godot/art/fx/dust.tscn", "godot/art/fx/cash.tscn", "godot/art/fx/confetti.tscn", "godot/art/fx/smoke.tscn", "godot/tests/test_fx.gd"],
  goal="A library of five `GPUParticles2D` scenes built from one table in `Fx`, plus `Fx.burst()` to fire a one-shot effect at a position. Numbers come from src/ui/particles.js KINDS and src/art/roomfx_world.js (steamPuffs, drawDust).",
  read=[TV, "src/ui/particles.js in the dev worktree /Users/leelangley/wt/webbwheresmycar/_dev (KINDS: the colours and timings this card copies; everything you need is also written below)", "Godot 4 `GPUParticles2D` and `ParticleProcessMaterial` (direction, spread, initial_velocity_min/max, gravity, scale_min/max, color_ramp, color_initial_ramp, emission_shape, emission_box_extents)", TREE],
  steps=[
   "Each of the five scene files is exactly these five lines (example for steam): `[gd_scene load_steps=2 format=3]`, `[ext_resource type=\"Script\" path=\"res://art/fx/fx.gd\" id=\"1\"]`, `[node name=\"Steam\" type=\"GPUParticles2D\"]`, `script = ExtResource(\"1\")`, `metadata/kind = \"steam\"`. Kinds and node names: steam/Steam, dust/Dust, cash/Cash, confetti/Confetti, smoke/Smoke. `fx.gd` is both the script of these scenes (`extends GPUParticles2D`; `_ready()` calls `Fx.setup(self, str(get_meta(\"kind\", \"steam\")))`) and the library: it declares `class_name Fx` and holds the static funcs.",
   "`godot/art/fx/fx.gd`: `class_name Fx`, `extends GPUParticles2D`. `const KINDS := PackedStringArray([\"steam\", \"dust\", \"cash\", \"confetti\", \"smoke\"])`. `const TABLE := {...}` with these numbers (all keys: amount, lifetime, one_shot, explosiveness, dir (Vector2), spread (degrees), vmin, vmax, gravity (Vector2), smin, smax, color (Color), colors (Array of Color, may be empty), box (Vector2, zero = point emitter)): steam: amount 12, lifetime 1.4, one_shot false, explosiveness 0.0, dir (0, -1), spread 20, vmin 18, vmax 30, gravity (0, -8), smin 1.5, smax 3.0, color `Color(1, 1, 1, 0.45)`, box zero; dust: amount 20, lifetime 6.0, one_shot false, explosiveness 0.0, dir (0, -1), spread 180, vmin 2, vmax 6, gravity (0, 0), smin 0.5, smax 1.0, color `Color(1.0, 0.914, 0.753, 0.35)`, box (200, 120); cash: amount 24, lifetime 1.3, one_shot true, explosiveness 0.95, dir (0, -1), spread 50, vmin 220, vmax 380, gravity (0, 700), smin 2.0, smax 3.0, color `Color(0.91, 0.725, 0.137, 1.0)`, box zero; confetti: amount 60, lifetime 2.2, one_shot true, explosiveness 0.9, dir (0, -1), spread 80, vmin 250, vmax 450, gravity (0, 420), smin 1.5, smax 3.0, color white, colors [`e8b923`, `d9483b`, `3fae49`, `70a4b2`, `6f3d86`, `ffffff`], box zero; smoke: amount 16, lifetime 1.6, one_shot false, explosiveness 0.0, dir (0, -1), spread 25, vmin 20, vmax 40, gravity (0, -6), smin 2.0, smax 5.0, color `Color(0.784, 0.784, 0.824, 0.5)`, box zero.",
   "`static func setup(p: GPUParticles2D, kind: String) -> bool`: false for an unknown kind. Otherwise fill the node from `TABLE[kind]`: `p.amount`, `p.lifetime`, `p.one_shot`, `p.explosiveness`, `p.emitting = not one_shot` (one-shot effects wait for `burst`), `p.texture = tex()` and `p.texture_filter = CanvasItem.TEXTURE_FILTER_NEAREST`, `p.process_material = ParticleProcessMaterial` with `direction = Vector3(dir.x, dir.y, 0)`, `spread`, `initial_velocity_min/max`, `gravity = Vector3(g.x, g.y, 0)`, `scale_min/max`, `color` (or for confetti `color_initial_ramp` = a `GradientTexture1D` whose Gradient has the 6 colours with offsets `i / 5.0`), `color_ramp` = a `GradientTexture1D` of a 2 colour Gradient (`Color(1, 1, 1, 1)` at 0.6 to `Color(1, 1, 1, 0)` at 1.0 for all kinds; smoke and steam: from `Color(1, 1, 1, 1)` at 0.0), and when `box != Vector2.ZERO`: `emission_shape = ParticleProcessMaterial.EMISSION_SHAPE_BOX`, `emission_box_extents = Vector3(box.x, box.y, 1)`. Set `p.set_meta(\"kind\", kind)` and return true. `static func tex() -> Texture2D`: cached in a `static var`; a 4x4 white `Image` (FORMAT_RGBA8) as `ImageTexture`.",
   "`static func burst(parent: Node, kind: String, pos: Vector2) -> GPUParticles2D`: loads `res://art/fx/<kind>.tscn` (null for an unknown kind), instantiates, `position = pos`, `parent.add_child(n)`; for one-shot kinds: `n.emitting = true`, `n.restart()` and `n.finished.connect(n.queue_free)`; returns the node. (`burst` needs a parent inside the tree, tests only check the failure case.)",
   "`godot/tests/test_fx.gd`: for each kind: `load(\"res://art/fx/<kind>.tscn\")` is a PackedScene; instantiate, call `Fx.setup(node, kind)` (the test calls it itself because `_ready` does not run out of tree): true; `amount` and `lifetime` equal the table; `one_shot` equals the table; `emitting` equals `not one_shot`; `process_material` is a ParticleProcessMaterial whose `initial_velocity_max` equals `vmax`; `texture_filter` is NEAREST. Specific: cash `amount` 24 and `explosiveness` 0.95; confetti `process_material.color_initial_ramp` is a GradientTexture1D whose gradient has 6 points; dust `emission_shape` is BOX with `emission_box_extents.x` 200; steam `process_material.gravity.y` is -8.0. `Fx.setup(n, \"zzz\")` is false; `Fx.burst(null, \"zzz\", Vector2.ZERO)` is null; `Fx.KINDS.size()` is 5; `Fx.tex().get_width()` is 4 and a second call returns the same object. Free all nodes."],
  accept=["`sh tools/godot/gtest.sh test_fx` last line is `GDTEST OK`."],
  oos=["No sound. No placing of effects in rooms (GDR cards call Fx.burst)."]),

 dict(id="GDA15", title="Sfx: overlapping sounds, sound setting, six art sounds", needs=["GDF12"],
  files=["godot/autoload/sfx.gd", "godot/tests/test_sfx.gd"],
  goal="GDF12 already synthesises the nine sounds of src/audio/sfx.js with ONE player, so a second sound cuts the first and the sound setting is ignored. Upgrade the Sfx autoload: four overlapping players, `Game.settings.sound` respected, an optional pitch, a duck volume, and six new synthesised sounds for the new art (engine, horn, steam, door, chime, thud).",
  read=[TV, "godot/autoload/sfx.gd as GDF12 left it (SOUNDS Dictionary of event Dictionaries `{type, freq, end_freq, start, dur, vol}`, `sound_names()`, `duration_of()`, `build_stream()`, `play()`, `set_muted()`, `set_music_duck()`, `unlock()`, `muted`, `music_ducked`, `_player`, `_streams`) and godot/tests/test_sfx.gd", "godot/autoload/game.gd (GDF10: `Game.settings` Dictionary with keys `crt`, `sound`, `music`)", "godot/tests/harness.gd"],
  steps=[
   "Add six entries to `SOUNDS` (same event format; `end_freq` equals `freq` except where a glide is given): `engine`: triangle freq 55 end_freq 110 start 0 dur 0.6 vol 0.3, and square freq 82 end_freq 165 start 0 dur 0.6 vol 0.08. `horn`: square 440 and square 554, both start 0 dur 0.35 vol 0.2. `steam`: noise freq 4000 end_freq 1500 start 0 dur 0.5 vol 0.2. `door`: noise freq 800 end_freq 100 start 0 dur 0.18 vol 0.4, and triangle freq 90 end_freq 50 start 0 dur 0.18 vol 0.3. `chime`: triangle 1047 start 0, triangle 1319 start 0.12, triangle 1568 start 0.24, each dur 0.25 vol 0.2. `thud`: triangle freq 70 end_freq 35 start 0 dur 0.2 vol 0.5. Nothing else in the synthesis code changes: `build_stream` already handles every event type.",
   "Overlap: replace the single `_player` by `var _players: Array[AudioStreamPlayer] = []` and `var _next := 0`. `const POOL := 4`. `func _ensure_players() -> void`: when `_players` is empty create `POOL` AudioStreamPlayer nodes (`add_child` each, works outside the tree) and store them. `func _pick_player() -> AudioStreamPlayer`: calls `_ensure_players()`, returns the first player whose `playing` is false, otherwise `_players[_next]` and then `_next = (_next + 1) % POOL`.",
   "`func play(sound: String, pitch: float = 1.0) -> bool` (the extra parameter is optional so old calls still work): false when `muted`; false for an unknown name; false when the Game setting says sound is off (`var g := get_node_or_null(\"/root/Game\")`; `if g != null and \"settings\" in g and not bool(g.settings.get(\"sound\", true)): return false`); false when not inside the tree (`is_inside_tree()`). Otherwise `var p := _pick_player()`, `p.stream = build_stream(sound)`, `p.pitch_scale = clampf(pitch, 0.5, 2.0)`, `p.volume_db = -8.0 if music_ducked else 0.0`, `p.play()`, return true. Keep `set_muted`, `set_music_duck`, `unlock` exactly as they are.",
   "Update `godot/tests/test_sfx.gd`: `test_names` now expects the sorted 15 names `bid, cash, chime, click, crash, door, engine, fail, fanfare, horn, paper, ring, steam, tada, thud`; `test_durations` gets these extra checks (eps 1e-9): engine 0.6, horn 0.35, steam 0.5, door 0.18, chime near 0.49, thud 0.2; `test_streams` loops over all 15 names (data size is `2 * int(ceil(duration_of(n) * 22050.0))`, not all zeros) and the peak of `thud` is at least 3000 and at most `0.5 * 32767 + 1`. New tests: `test_pool`: on a fresh instance `_ensure_players()` gives `_players.size()` 4 and `get_child_count()` 4, calling it twice keeps 4, `_pick_player()` returns `_players[0]` when none is playing; `test_settings`: a stand-in for the Game autoload cannot be added to the tree here, so only check the unchanged rules: `play(\"click\")` and `play(\"click\", 1.5)` are false outside the tree and `play(\"nope\")` is false; `test_duck_flag`: `set_music_duck(true)` makes `music_ducked` true. Keep every existing GDF12 test passing."],
  accept=["`sh tools/godot/gtest.sh test_sfx` last line is `GDTEST OK`.", "`sh tools/godot/gtest.sh` (everything) ends with `GDTEST OK`."],
  oos=["No music, no audio files, no buses. Do not rename or remove any existing public func or var of Sfx."]),

 dict(id="GDA16", title="App icon and launch image", needs=["GDF01"],
  files=["tools/art/make_launch.py", "tools/art/test_make_launch.sh", "godot/icon.svg", "godot/art/launch.png"],
  goal="A small python3 script draws the game's pixel icon and launch image from ONE rectangle list (a little orange two-door car on a purple night street) and writes `godot/icon.svg` (the Godot project icon, 512 px via viewBox) and `godot/art/launch.png` (1280x720, for the launch screen).",
  read=["docs/GODOT.md (colours: night purple #14102a / #2b2550)", "tools/art/pixelate.py (to see what the repo already has; this script needs no Blender and no PIL)"],
  steps=[
   "`tools/art/make_launch.py` (python3 standard library only; `python3 tools/art/make_launch.py [--check]`). Constant `CAR` is the list of rectangles `(x, y, w, h, colour)` on a 32 x 21 cell grid, drawn in this order: `(2, 20, 28, 1, '#0b0918')` shadow; `(1, 10, 30, 6, '#c96f32')` body; `(22, 8, 8, 2, '#c96f32')` bonnet; `(7, 4, 15, 6, '#c96f32')` cabin; `(8, 4, 13, 1, '#e8a070')` roof highlight; `(1, 14, 30, 2, '#9a4f22')` lower shade; `(9, 5, 5, 4, '#a8d0e0')` and `(15, 5, 6, 4, '#a8d0e0')` windows; `(0, 13, 2, 3, '#e8e8ee')` and `(30, 13, 2, 3, '#e8e8ee')` bumpers; `(28, 10, 2, 2, '#ffe9a8')` headlamp; `(1, 10, 2, 2, '#d82020')` tail lamp; `(5, 14, 6, 6, '#14102a')` and `(21, 14, 6, 6, '#14102a')` tyres; `(7, 16, 2, 2, '#e8e8ee')` and `(23, 16, 2, 2, '#e8e8ee')` hubs.",
   "Icon: grid 32 x 32. Rectangles in order: `(0, 0, 32, 32, '#2b2550')` background; `(0, 27, 32, 5, '#14102a')` road; stars `(4, 3, 1, 1, '#ffffff')`, `(12, 6, 1, 1, '#ffffff')`, `(20, 2, 1, 1, '#ffffff')`, `(27, 8, 1, 1, '#ffffff')`; moon `(24, 3, 4, 4, '#ffe9a8')`; then every rectangle of `CAR` with y offset +7 (x offset 0). `godot/icon.svg`: `<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"512\" height=\"512\" viewBox=\"0 0 32 32\" shape-rendering=\"crispEdges\">` followed by one `<rect x= y= width= height= fill=/>` per rectangle (integers, one per line), `</svg>`, trailing newline, ASCII only.",
   "Launch image: grid 64 x 36, scale 20 (1280 x 720). Rectangles in order: `(0, 0, 64, 18, '#14102a')`, `(0, 18, 64, 10, '#1d1840')`, `(0, 28, 64, 8, '#2b2550')` sky bands; ten stars `(5, 3)`, `(14, 8)`, `(22, 4)`, `(31, 10)`, `(40, 3)`, `(47, 7)`, `(55, 4)`, `(60, 11)`, `(9, 13)`, `(36, 14)` each `1 x 1` white; moon `(52, 5, 4, 4, '#ffe9a8')`; road `(0, 28, 64, 8, '#14102a')`; kerb line `(0, 28, 64, 1, '#6c5eb5')`; every rectangle of `CAR` with offset (16, 8) (the car is centred, 32 cells wide, its wheels on the road). Write `godot/art/launch.png` as an 8-bit RGB PNG (colour type 2) with `zlib` and `struct` (signature, IHDR, IDAT with filter byte 0 per row, IEND; correct CRC). Rasterise by filling pixel rows; do not draw anti-aliased edges.",
   "`--check` re-reads the written PNG header and prints `LAUNCH OK 1280x720` and `ICON OK rects=<n>`; the plain run writes both files and prints `WROTE godot/icon.svg godot/art/launch.png`. Output is deterministic (running twice gives identical files).",
   "`tools/art/test_make_launch.sh`: runs the script and then `--check`; requires `file godot/art/launch.png` to say `1280 x 720`; parses `godot/icon.svg` with python3 `xml.etree.ElementTree`, requires `viewBox` `0 0 32 32`, at least 25 `rect` elements, and no byte above 126 in the file; md5 of both outputs identical after a second run. Prints `LAUNCH ASSETS OK`. Commit the two generated files."],
  accept=["`sh tools/art/test_make_launch.sh` last line is `LAUNCH ASSETS OK`.", "Open `godot/art/launch.png` with the Read tool and describe it in your reply (expected: dark purple night sky with white stars and a yellow moon, a purple road, a small orange two-door car with two light-blue windows in the middle)."],
  oos=["Do not edit project.godot (GDF01 owns it; the planner-in-chief adds `config/icon=\"res://icon.svg\"`). No text on the launch image."]),

 dict(id="GDA17", title="Contact sheet of all cars (one review image)", needs=["GDA03", "GDF01"],
  files=["tools/godot/contact_sheet_cars.sh", "godot/art/car_sheet.gd", "godot/art/car_sheet.tscn", "godot/tests/test_car_sheet.gd"],
  goal="`sh tools/godot/contact_sheet_cars.sh [out.png]` renders every car of `res://art/cars/manifest.json` on one 1280x720 review image: for each car a side view at wear (index mod 4) and a three-quarter view at wear 0, with the game name and wear level written on each cell. Planners and reviewers use it to check recognisable shapes, paint, wear and chrome at a glance.",
  read=[TV, "tools/godot/gshot.sh (renders one scene on CASE and copies the PNG back; usage `gshot.sh <scene> <out.png> [frames] [WxH]`)", "godot/art/carview.gd (GDA03: set_car, set_view, set_wear, `shrink` is set through set_view; to get a coarser pixel size in small cells call `Box.stretch_shrink = 2` via `get_node(\"Box\")`)", TREE],
  steps=[
   "`godot/art/car_sheet.tscn`: root `Control` named `CarSheet` (`custom_minimum_size = Vector2(1280, 720)`, `layout_mode = 3`, `anchors_preset = 0`, `script = ExtResource(\"1\")` = res://art/car_sheet.gd). `car_sheet.gd`: `class_name CarSheet`, `extends Control`, `const COLS := 4`, `const W := 1280.0`, `const H := 720.0`; `build()` (idempotent, `_ready()` calls it): `size = Vector2(W, H)`; a `ColorRect` `Back` full rect `1b1740`; `ids := CarView.manifest().get(\"cars\", {}).keys()` sorted; `cells := ids.size() * 2`; `rows := ceili(float(cells) / COLS)`; `cell := Vector2(W / COLS, H / max(rows, 1))`. For car index `i`: cell `2*i` is the side view with `wear = float(i % 4)`, cell `2*i+1` the three-quarter view with wear 0.0. Cell `k` is at column `k % COLS`, row `k / COLS`. Each cell is a `CarView` (named `Cell_<k>`, `position` = column * cell.x, row * cell.y, `size` = cell, `custom_minimum_size` = cell) with `build()`, `set_view(...)`, then `get_node(\"Box\").stretch_shrink = 2`, `set_car(id)`, `set_wear(...)`, plus a `Label` child named `Tag` (font size 12, white, outline black 3 px, position (4, 2)) with the text `<game_name> w<wear int>` (game name from the manifest; ASCII).",
   "`tools/godot/contact_sheet_cars.sh` (sh): `HERE=$(cd \"$(dirname \"$0\")\" && pwd)`; `OUT=${1:-/tmp/car_sheet.png}`; `sh \"$HERE/gshot.sh\" art/car_sheet.tscn \"$OUT\" 40 1280x720`; echo `SHEET $OUT`. Pass the exit status of gshot on. Header comment with usage.",
   "`godot/tests/test_car_sheet.gd`: instantiate `res://art/car_sheet.tscn`, `build()`; with the manifest's N cars the node has `Back` plus `2 * N` children named `Cell_0` .. (check `Cell_0` and `Cell_<2N-1>` exist); `Cell_0` is a CarView with `view` `side`, `car_id` equal to the first sorted id and `wear` 0.0; `Cell_2` has wear 1.0 (car index 1), `Cell_8` (car index 4) has wear 0.0; `Cell_1` has view `three_quarter` and wear 0.0; cell sizes are `(320, 720 / rows)`; each `Cell_k` has a child `Tag` whose text contains `w` and a game name from the manifest; `Cell_0.get_node(\"Box\").stretch_shrink` is 2. Free the node.",
   "Run `sh tools/godot/contact_sheet_cars.sh /tmp/gda17.png`; the output must contain NO line with `ERROR`. Open the PNG with the Read tool and DESCRIBE it in your final reply: how many cars are visible, whether each shows paint, glass, chrome and wheels, whether the wear levels visibly differ (dirt, rust, dull paint, cracked glass on the wreck), anything black or cut off."],
  accept=["`sh tools/godot/gtest.sh test_car_sheet` last line is `GDTEST OK`.", "`sh tools/godot/contact_sheet_cars.sh /tmp/gda17.png` prints `SHEET /tmp/gda17.png`, no `ERROR` line; you viewed the PNG and described it."],
  oos=["Do not change CarView. The sheet is a review tool, not a game scene."]),
]
